import React, { useEffect, useMemo, useRef, useState } from 'react';
import { 
  Droplets, Sparkles, Target, Flame, TrendingUp, TrendingDown, 
  Award, Zap, ChevronDown, ChevronUp, Clock
} from 'lucide-react';

interface BasicTodayRingProps {
  waterIntake: number;
  waterGoal: number;
  streak: number;
  completionRate: number;
  yesterdayIntake?: number;
  weeklyTrend?: number[];
}

// Animated counter with proper easing
function useAnimatedCounter(target: number, duration = 1000) {
  const [current, setCurrent] = useState(0);

  useEffect(() => {
    let raf = 0;
    const startTime = performance.now();
    const from = current;
    const diff = target - from;

    const animate = (now: number) => {
      const progress = Math.min((now - startTime) / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3); // ease-out-cubic per design system

      setCurrent(from + diff * eased);

      if (progress < 1) {
        raf = requestAnimationFrame(animate);
      } else {
        setCurrent(target);
      }
    };

    raf = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(raf);
  }, [target]);

  return Math.round(current);
}

// Confetti particle - design system compliant
function ConfettiParticle({ delay, index }: { delay: number; index: number }) {
  const [styleData] = useState(() => {
    // Design system colors only - cyan, emerald, amber
    const colors = ['#22d3ee', '#34d399', '#fbbf24', '#38bdf8'];
    return {
      color: colors[index % colors.length],
      x: Math.random() * 200 - 100,
      rotation: Math.random() * 720 - 360,
      scale: Math.random() * 0.7 + 0.5,
    };
  });

  return (
    <div
      className="absolute rounded-full opacity-0"
      style={
        {
          width: `${styleData.scale * 6}px`,
          height: `${styleData.scale * 6}px`,
          backgroundColor: styleData.color,
          animation: `confetti-fall 1.6s ease-out ${delay}s forwards`,
          '--x': `${styleData.x}px`,
          '--rotation': `${styleData.rotation}deg`,
        } as React.CSSProperties
      }
    />
  );
}

// Enhanced metric row with hover states
function MetricRow({
  icon: Icon,
  title,
  subtitle,
  value,
  secondaryInfo,
  accentClass,
  bgClass,
  borderClass,
  isExpandable = false,
  isExpanded = false,
  onToggle,
}: {
  icon: React.ElementType;
  title: string;
  subtitle: string;
  value: React.ReactNode;
  secondaryInfo?: React.ReactNode;
  accentClass: string;
  bgClass: string;
  borderClass: string;
  isExpandable?: boolean;
  isExpanded?: boolean;
  onToggle?: () => void;
}) {
  return (
    <button
      onClick={isExpandable ? onToggle : undefined}
      disabled={!isExpandable}
      className={`w-full flex items-center justify-between rounded-2xl border ${borderClass} ${bgClass} p-4 backdrop-blur-xl transition-all duration-200 ease-out ${
        isExpandable ? 'hover:bg-slate-800/60 hover:border-cyan-500/30 active:scale-[0.98]' : ''
      }`}
      aria-label={`${title}: ${value}`}
      role={isExpandable ? 'button' : undefined}
      aria-expanded={isExpandable ? isExpanded : undefined}
    >
      <div className="flex items-center gap-3">
        <div className={`flex h-10 w-10 items-center justify-center rounded-xl border ${borderClass} ${bgClass}`}>
          <Icon size={18} className={accentClass} aria-hidden="true" />
        </div>
        <div className="text-left">
          <p className="text-sm font-black text-white">{title}</p>
          <p className={`text-[10px] font-bold uppercase tracking-widest ${accentClass}/80`}>
            {subtitle}
          </p>
        </div>
      </div>
      <div className="flex items-center gap-2">
        <div className="text-right">
          <span className="text-lg font-black text-white">{value}</span>
          {secondaryInfo && (
            <span className="text-[10px] text-slate-400 mt-0.5 block">{secondaryInfo}</span>
          )}
        </div>
        {isExpandable && (
          <div className="text-slate-400">
            {isExpanded ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
          </div>
        )}
      </div>
    </button>
  );
}

// Streak badge with proper styling
function StreakBadge({ streak }: { streak: number }) {
  if (streak < 3) return null;
  
  return (
    <div className="absolute top-4 right-4 z-20 animate-in fade-in slide-in-from-right duration-300">
      <div 
        className="glass-card-strong px-3 py-2 flex items-center gap-2 border-orange-500/20"
        style={streak >= 7 ? { animation: 'float-soft 3s ease-in-out infinite' } : undefined}
        role="status"
        aria-label={`${streak} day streak`}
      >
        <Flame size={16} className="text-orange-400" aria-hidden="true" />
        <div className="text-left">
          <p className="text-[8px] uppercase tracking-widest text-slate-400 font-bold leading-none mb-0.5">
            Liên tục
          </p>
          <p className="text-lg leading-none font-black text-orange-400">{streak}</p>
        </div>
      </div>
    </div>
  );
}

function getMilestone(percent: number) {
  if (percent >= 100) return { text: 'Hoàn thành xuất sắc!', color: 'text-emerald-400' };
  if (percent >= 75) return { text: 'Sắp đạt mục tiêu!', color: 'text-cyan-400' };
  if (percent >= 50) return { text: 'Đang tiến triển tốt', color: 'text-sky-400' };
  if (percent >= 25) return { text: 'Bắt đầu tốt', color: 'text-blue-400' };
  return { text: 'Hãy bắt đầu uống nước', color: 'text-slate-400' };
}

export default function BasicTodayRingUltimate({
  waterIntake,
  waterGoal,
  streak,
  completionRate,
  yesterdayIntake = 0,
  weeklyTrend = [],
}: BasicTodayRingProps) {
  const [showCelebration, setShowCelebration] = useState(false);
  const [mounted, setMounted] = useState(false);
  const [expandedMetric, setExpandedMetric] = useState<string | null>(null);
  const prevCompletedRef = useRef(false);

  const todayProgressRaw = waterGoal > 0 ? (waterIntake / waterGoal) * 100 : 0;
  const dailyPercent = Math.min(Math.max(todayProgressRaw, 0), 100);
  const weeklyPercent = Math.min(Math.max(completionRate, 0), 100);
  const streakPercent = Math.min(Math.max((streak / 30) * 100, 0), 100);
  const isCompleted = dailyPercent >= 100;

  const animatedPercent = useAnimatedCounter(dailyPercent, 1000);
  const milestone = useMemo(() => getMilestone(dailyPercent), [dailyPercent]);
  
  // Comparison with yesterday
  const comparison = yesterdayIntake > 0 ? waterIntake - yesterdayIntake : 0;

  // Ring configuration - design system compliant
  const ring = useMemo(
    () => ({
      outer: { r: 110, strokeWidth: 14 },
      middle: { r: 90, strokeWidth: 14 },
      inner: { r: 70, strokeWidth: 14 },
    }),
    []
  );

  const cOuter = 2 * Math.PI * ring.outer.r;
  const cMiddle = 2 * Math.PI * ring.middle.r;
  const cInner = 2 * Math.PI * ring.inner.r;

  const offOuter = cOuter - (dailyPercent / 100) * cOuter;
  const offMiddle = cMiddle - (weeklyPercent / 100) * cMiddle;
  const offInner = cInner - (streakPercent / 100) * cInner;

  useEffect(() => {
    const t = window.setTimeout(() => setMounted(true), 120);
    return () => window.clearTimeout(t);
  }, []);

  useEffect(() => {
    if (isCompleted && !prevCompletedRef.current) {
      const t1 = window.setTimeout(() => setShowCelebration(true), 0);
      const t2 = window.setTimeout(() => setShowCelebration(false), 2000);
      return () => { window.clearTimeout(t1); window.clearTimeout(t2); };
    }
    prevCompletedRef.current = isCompleted;
  }, [isCompleted]);

  const glow = Math.min(dailyPercent / 100, 1);

  return (
    <div className="px-5">
      <style>{`
        @keyframes confetti-fall {
          0% {
            transform: translate(0, 0) rotate(0deg) scale(1);
            opacity: 1;
          }
          100% {
            transform: translate(var(--x), 200px) rotate(var(--rotation)) scale(0.2);
            opacity: 0;
          }
        }

        @keyframes float-soft {
          0%, 100% { transform: translateY(0px); }
          50% { transform: translateY(-6px); }
        }

        .ring-glow {
          filter: drop-shadow(0 0 ${8 + glow * 12}px rgba(34, 211, 238, ${0.2 + glow * 0.4}));
        }

        .number-glow {
          text-shadow: 0 0 20px rgba(34, 211, 238, ${0.2 + glow * 0.4});
        }
      `}</style>

      <div className="glass-card p-5 pb-4 relative overflow-hidden">
        {/* Background gradient overlay */}
        <div className="pointer-events-none absolute inset-0 bg-gradient-to-br from-cyan-500/5 via-transparent to-emerald-500/5" />

        {/* Streak badges */}
        <StreakBadge streak={streak} />

        {/* Celebration confetti */}
        {showCelebration && (
          <div className="pointer-events-none absolute inset-0 z-30 overflow-hidden flex items-center justify-center">
            {Array.from({ length: 24 }).map((_, i) => (
              <ConfettiParticle key={i} delay={i * 0.04} index={i} />
            ))}
          </div>
        )}

        {/* Header */}
        <div className="relative z-10 mb-2 flex items-start justify-between gap-3">
          <div>
            <div className="flex items-center gap-2">
              <p className="text-xs font-bold uppercase tracking-widest text-cyan-400">
                Tiến độ hôm nay
              </p>
              {isCompleted && (
                <Sparkles size={14} className="text-emerald-400" aria-hidden="true" />
              )}
            </div>
            <p className={`mt-1.5 text-sm font-medium ${milestone.color}`}>
              {milestone.text}
            </p>
          </div>
        </div>

        {/* 3 Rings visualization */}
        <div className="relative z-10 flex justify-center mb-6">
          <div className="relative h-64 w-64">
            <svg 
              className="ring-glow h-full w-full -rotate-90" 
              viewBox="0 0 256 256" 
              aria-label={`Water intake progress: ${Math.round(dailyPercent)}%`}
              role="img"
            >
              <defs>
                {/* Design system compliant gradients */}
                <linearGradient id="volGradient" x1="0%" y1="0%" x2="100%" y2="100%">
                  <stop offset="0%" stopColor="#22d3ee" /> {/* cyan-400 */}
                  <stop offset="100%" stopColor="#06b6d4" /> {/* cyan-500 */}
                </linearGradient>
                <linearGradient id="consGradient" x1="0%" y1="0%" x2="100%" y2="100%">
                  <stop offset="0%" stopColor="#34d399" /> {/* emerald-400 */}
                  <stop offset="100%" stopColor="#10b981" /> {/* emerald-500 */}
                </linearGradient>
                <linearGradient id="streakGradient" x1="0%" y1="0%" x2="100%" y2="100%">
                  <stop offset="0%" stopColor="#fb923c" /> {/* orange-400 */}
                  <stop offset="100%" stopColor="#f97316" /> {/* orange-500 */}
                </linearGradient>
              </defs>

              {/* Outer ring - Volume (Cyan) */}
              <circle
                cx="128"
                cy="128"
                r={ring.outer.r}
                fill="none"
                stroke="var(--dw-surface-2)"
                strokeWidth={ring.outer.strokeWidth}
              />
              <circle
                cx="128"
                cy="128"
                r={ring.outer.r}
                fill="none"
                stroke="url(#volGradient)"
                strokeWidth={ring.outer.strokeWidth}
                strokeLinecap="round"
                strokeDasharray={cOuter}
                strokeDashoffset={mounted ? offOuter : cOuter}
                style={{ transition: 'stroke-dashoffset 1.2s cubic-bezier(0.34, 1.56, 0.64, 1)' }}
              />

              {/* Middle ring - Consistency (Emerald) */}
              <circle
                cx="128"
                cy="128"
                r={ring.middle.r}
                fill="none"
                stroke="var(--dw-surface-2)"
                strokeWidth={ring.middle.strokeWidth}
              />
              <circle
                cx="128"
                cy="128"
                r={ring.middle.r}
                fill="none"
                stroke="url(#consGradient)"
                strokeWidth={ring.middle.strokeWidth}
                strokeLinecap="round"
                strokeDasharray={cMiddle}
                strokeDashoffset={mounted ? offMiddle : cMiddle}
                style={{ transition: 'stroke-dashoffset 1.2s cubic-bezier(0.34, 1.56, 0.64, 1)' }}
              />

              {/* Inner ring - Streak (Orange) */}
              <circle
                cx="128"
                cy="128"
                r={ring.inner.r}
                fill="none"
                stroke="var(--dw-surface-2)"
                strokeWidth={ring.inner.strokeWidth}
              />
              <circle
                cx="128"
                cy="128"
                r={ring.inner.r}
                fill="none"
                stroke="url(#streakGradient)"
                strokeWidth={ring.inner.strokeWidth}
                strokeLinecap="round"
                strokeDasharray={cInner}
                strokeDashoffset={mounted ? offInner : cInner}
                style={{ transition: 'stroke-dashoffset 1.2s cubic-bezier(0.34, 1.56, 0.64, 1)' }}
              />

              {/* Milestone markers */}
              {[25, 50, 75, 100].map((milestone) => {
                const angle = (milestone / 100) * 2 * Math.PI - Math.PI / 2;
                return (
                  <g key={milestone}>
                    <circle
                      cx={128 + ring.outer.r * Math.cos(angle)}
                      cy={128 + ring.outer.r * Math.sin(angle)}
                      r="2.5"
                      fill={dailyPercent >= milestone ? "#22d3ee" : "rgba(255,255,255,0.08)"}
                      className="transition-all duration-300"
                    />
                    <circle
                      cx={128 + ring.middle.r * Math.cos(angle)}
                      cy={128 + ring.middle.r * Math.sin(angle)}
                      r="2.5"
                      fill={weeklyPercent >= milestone ? "#34d399" : "rgba(255,255,255,0.08)"}
                      className="transition-all duration-300"
                    />
                    <circle
                      cx={128 + ring.inner.r * Math.cos(angle)}
                      cy={128 + ring.inner.r * Math.sin(angle)}
                      r="2.5"
                      fill={streakPercent >= milestone ? "#fb923c" : "rgba(255,255,255,0.08)"}
                      className="transition-all duration-300"
                    />
                  </g>
                );
              })}
            </svg>

            {/* Center content */}
            <div className="absolute inset-0 flex flex-col items-center justify-center text-center">
              {isCompleted ? (
                <Award size={28} className="mb-1.5 text-emerald-400" aria-hidden="true" />
              ) : (
                <Droplets size={28} className="mb-1.5 text-cyan-400" aria-hidden="true" />
              )}
              <p className="text-[42px] font-black leading-none tracking-tight text-transparent bg-gradient-to-br from-cyan-400 to-cyan-500 bg-clip-text number-glow">
                {mounted ? animatedPercent : 0}%
              </p>
              <p className="mt-1.5 text-[10px] font-bold uppercase tracking-widest text-slate-400">
                {isCompleted ? 'Hoàn thành' : 'Hôm nay'}
              </p>
            </div>

            {/* Rotating Lightning Bolt */}
            <div 
              className="absolute inset-0 pointer-events-none flex items-center justify-center z-20"
              style={{ animation: 'spin 12s linear infinite' }}
            >
              <div 
                className="w-5 h-5 rounded-full bg-slate-950 border border-amber-500/50 flex items-center justify-center shadow-[0_0_12px_rgba(251,191,36,0.6)]" 
                style={{ transform: `translateY(-${ring.outer.r}px)` }}
              >
                <Zap size={10} className="text-amber-400" />
              </div>
            </div>
          </div>
        </div>

        {/* Metric rows */}
        <div className="relative z-10 space-y-2.5">
          {/* Volume metric */}
          <MetricRow
            icon={Droplets}
            title="Nạp nước"
            subtitle="Thể tích"
            value={
              <>
                {waterIntake.toLocaleString('vi-VN')}
                <span className="ml-1 text-xs font-medium text-slate-500">
                  / {waterGoal.toLocaleString('vi-VN')}ml
                </span>
              </>
            }
            secondaryInfo={
              comparison !== 0 ? (
                <div className="flex items-center gap-1">
                  {comparison > 0 ? (
                    <>
                      <TrendingUp size={10} className="text-emerald-400" />
                      <span className="text-emerald-400">+{comparison}ml</span>
                    </>
                  ) : (
                    <>
                      <TrendingDown size={10} className="text-orange-400" />
                      <span className="text-orange-400">{comparison}ml</span>
                    </>
                  )}
                </div>
              ) : undefined
            }
            accentClass="text-cyan-400"
            bgClass="bg-cyan-500/10"
            borderClass="border-cyan-500/20"
            isExpandable={weeklyTrend.length > 0}
            isExpanded={expandedMetric === 'volume'}
            onToggle={() => setExpandedMetric(expandedMetric === 'volume' ? null : 'volume')}
          />

          {/* Expanded volume details */}
          {expandedMetric === 'volume' && weeklyTrend.length > 0 && (
            <div className="glass-card p-4 space-y-3 animate-in fade-in slide-in-from-top duration-200">
              <p className="text-[10px] font-bold uppercase tracking-widest text-slate-400">
                Xu hướng 7 ngày
              </p>
              <div className="flex items-end justify-center gap-1 h-16">
                {weeklyTrend.slice(-7).map((value, i) => {
                  const max = Math.max(...weeklyTrend);
                  const min = Math.min(...weeklyTrend);
                  const range = max - min || 1;
                  const height = ((value - min) / range) * 64;
                  const isToday = i === weeklyTrend.length - 1;
                  return (
                    <div
                      key={i}
                      className={`w-6 rounded-t-lg transition-all duration-300 ${
                        isToday ? 'bg-cyan-400' : 'bg-cyan-400/40'
                      }`}
                      style={{ height: `${Math.max(height, 8)}px` }}
                      role="presentation"
                    />
                  );
                })}
              </div>
              <div className="flex items-center justify-between text-xs">
                <span className="text-slate-400">Trung bình</span>
                <span className="font-bold text-white">
                  {Math.round(weeklyTrend.reduce((a, b) => a + b, 0) / weeklyTrend.length)}%
                </span>
              </div>
            </div>
          )}

          {/* Consistency metric */}
          <MetricRow
            icon={Target}
            title="Mục tiêu tuần"
            subtitle="Đều đặn"
            value={
              <>
                {Math.round(weeklyPercent)}
                <span className="ml-1 text-xs font-medium text-slate-500">%</span>
              </>
            }
            accentClass="text-emerald-400"
            bgClass="bg-emerald-500/10"
            borderClass="border-emerald-500/20"
          />

          {/* Streak metric */}
          <MetricRow
            icon={Flame}
            title="Độ kiên trì"
            subtitle="Liên tục"
            value={
              <>
                {streak}
                <span className="ml-1 text-xs font-medium text-slate-500">ngày</span>
              </>
            }
            secondaryInfo={
              streak >= 7 ? <span className="text-orange-400"><Flame size={14} className="inline mr-1" />Đang cháy</span> : undefined
            }
            accentClass="text-orange-400"
            bgClass="bg-orange-500/10"
            borderClass="border-orange-500/20"
          />
        </div>

        {/* Quick stats footer */}
        {yesterdayIntake > 0 && (
          <div className="relative z-10 mt-4 pt-4 border-t border-white/5">
            <div className="flex items-center justify-between text-sm">
              <div className="flex items-center gap-2 text-slate-400">
                <Clock size={14} aria-hidden="true" />
                <span>Hôm qua</span>
              </div>
              <div className="flex items-center gap-2">
                <span className="font-bold text-white">
                  {yesterdayIntake.toLocaleString('vi-VN')}ml
                </span>
                {comparison !== 0 && (
                  <span className={`text-xs font-bold ${comparison > 0 ? 'text-emerald-400' : 'text-orange-400'}`}>
                    ({comparison > 0 ? '+' : ''}{comparison}ml)
                  </span>
                )}
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useEffect, useState, useMemo } from 'react';
import { supabase } from '../lib/supabase';
import { Trophy, Target, Lock, CheckCircle2, Flame, Loader2 } from 'lucide-react';
import { toast } from 'sonner';

interface Challenge {
  id: string;
  title: string;
  description: string;
  category: string;
  stake_wp: number;
  reward_wp: number;
  duration_days: number;
}

interface UserChallenge {
  id: string;
  challenge_id: string;
  status: string;
  progress_days: number;
  joined_at: string;
}

interface ChallengesListProps {
  userId: string;
  userPoints: number;
  onChallengeJoined: (stakedWp: number) => void;
}

export default function ChallengesList({ userId, userPoints, onChallengeJoined }: ChallengesListProps) {
  const [challenges, setChallenges] = useState<Challenge[]>([]);
  const [userChallenges, setUserChallenges] = useState<UserChallenge[]>([]);
  const [loading, setLoading] = useState(true);
  const [joiningId, setJoiningId] = useState<string | null>(null);
  const [activeCategory, setActiveCategory] = useState('all');

  const fetchData = async () => {
    if (!userId || userId === 'undefined') return;
    setLoading(true);
    try {
      const [challengesRes, userChallengesRes] = await Promise.all([
        supabase.from('challenges').select('*').order('stake_wp', { ascending: true }),
        supabase.from('user_challenges').select('*').eq('user_id', userId).eq('status', 'active')
      ]);
      
      if (challengesRes.error) throw challengesRes.error;
      if (userChallengesRes.error) throw userChallengesRes.error;

      setChallenges(challengesRes.data || []);
      setUserChallenges(userChallengesRes.data || []);
    } catch (error: unknown) {
      console.error("Error fetching challenges:", error);
      toast.error("Không thể tải danh sách thử thách");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [userId]);

  const handleJoin = async (challenge: Challenge) => {
    if (userPoints < challenge.stake_wp) {
      toast.error("Không đủ WP để tham gia thử thách này!");
      return;
    }

    setJoiningId(challenge.id);
    const toastId = toast.loading("Đang đăng ký tham gia...");

    try {
      const { error } = await supabase.rpc('join_challenge', {
        p_user_id: userId,
        p_challenge_id: challenge.id,
        p_stake_wp: challenge.stake_wp
      });

      if (error) throw error;

      toast.success(`Đã tham gia: ${challenge.title}`, { id: toastId });

      // Notify the parent component that the challenge was joined and pass the staked amount.
      onChallengeJoined(challenge.stake_wp);
      
      // Improvement: Only refetch user challenges instead of all data.
      const { data: updatedUserChallenges, error: refetchError } = await supabase
        .from('user_challenges')
        .select('*')
        .eq('user_id', userId)
        .eq('status', 'active');

      if (refetchError) throw refetchError;
      setUserChallenges(updatedUserChallenges || []);

    } catch (error: unknown) {
      console.error("Error joining challenge:", error);
      toast.error("Lỗi khi tham gia thử thách. Vui lòng thử lại.", { id: toastId });
    } finally {
      setJoiningId(null);
    }
  };
  
  const categories = useMemo(() => ['all', ...Array.from(new Set(challenges.map(c => c.category).filter(Boolean)))], [challenges]);
  const filteredChallenges = useMemo(() => challenges.filter(c => activeCategory === 'all' || c.category === activeCategory), [challenges, activeCategory]);

  const ChallengeSkeleton = () => (
    <div className="relative overflow-hidden p-5 rounded-[2rem] border border-slate-800 bg-slate-900/40 animate-pulse">
      <div className="flex justify-between items-start mb-3"><div className="pr-3 space-y-2"><div className="h-5 w-48 bg-slate-700/50 rounded"></div><div className="h-3 w-64 bg-slate-700/50 rounded"></div></div><div className="p-2 rounded-xl bg-slate-800/50 border border-slate-700/50"><div className="h-2 w-16 bg-slate-700/50 rounded mb-1"></div><div className="h-5 w-12 bg-slate-700/50 rounded"></div></div></div>
      <div className="flex items-center justify-between mt-4 pt-4 border-t border-slate-700/50"><div className="flex items-center gap-2"><div className="h-8 w-20 bg-slate-800/80 rounded-lg"></div><div className="h-8 w-24 bg-slate-800/80 rounded-lg"></div></div><div className="h-10 w-24 bg-slate-800/80 rounded-xl"></div></div>
    </div>
  );

  if (loading) {
    return (
      <div className="space-y-4">
        <div className="flex items-center justify-between px-2 animate-pulse"><div className="h-6 w-40 bg-slate-700/50 rounded"></div><div className="h-6 w-48 bg-slate-800 rounded-lg"></div></div>
        <div className="grid grid-cols-1 gap-3">
          <ChallengeSkeleton />
          <ChallengeSkeleton />
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between px-2">
        <h2 className="text-xl font-bold text-slate-50 flex items-center gap-2">
          <Target size={20} className="text-cyan-400" />
          Thử thách
        </h2>
        <span className="text-[10px] font-bold text-slate-400 bg-slate-800 px-2 py-1 rounded-lg uppercase tracking-wider">Cược WP để nhận thưởng</span>
      </div>

      {categories.length > 2 && (
        <div className="flex gap-2 p-1 bg-slate-900/80 rounded-full border border-slate-700/50">
          {categories.map(category => (
            <button
              key={category}
              onClick={() => setActiveCategory(category)}
              className={`flex-1 py-2 text-xs font-bold rounded-lg transition-colors capitalize ${activeCategory === category ? 'bg-cyan-500/20 text-cyan-400' : 'text-slate-400 hover:bg-white/5'}`}
            >
              {category === 'all' ? 'Tất cả' : category}
            </button>
          ))}
        </div>
      )}

      <div className="grid grid-cols-1 gap-3">
        {filteredChallenges.map(challenge => {
          const activeEntry = userChallenges.find(uc => uc.challenge_id === challenge.id);
          const isActive = !!activeEntry;
          const canAfford = userPoints >= challenge.stake_wp;
          const isJoining = joiningId === challenge.id;

          return (
            <div 
              key={challenge.id}
              className={`relative overflow-hidden p-5 rounded-[2rem] border transition-all duration-300 ${
                isActive 
                  ? 'bg-emerald-500/10 border-emerald-500/30 shadow-[0_0_15px_rgba(16,185,129,0.1)]' 
                  : 'bg-slate-900/40 border-slate-800 hover:border-cyan-500/50'
              }`}
            >
              <div className="flex justify-between items-start mb-3">
                <div className="pr-3">
                  <h3 className="font-bold text-white text-lg tracking-tight leading-tight">{challenge.title}</h3>
                  <p className="text-slate-400 text-xs mt-1.5 leading-relaxed">{challenge.description}</p>
                </div>
                {isActive ? (
                  <div className="flex items-center gap-1 bg-emerald-500/20 text-emerald-400 px-2.5 py-1 rounded-full text-[10px] font-black uppercase tracking-wider border border-emerald-500/30 whitespace-nowrap shadow-inner flex-shrink-0">
                    <CheckCircle2 size={12} /> Đang chạy
                  </div>
                ) : (
                  <div className="text-right whitespace-nowrap flex-shrink-0 bg-slate-800/50 p-2 rounded-xl border border-slate-700/50">
                    <div className="text-[9px] text-slate-500 font-bold uppercase tracking-wider mb-0.5">Phần thưởng</div>
                    <div className="text-yellow-400 font-black text-sm flex items-center gap-1">
                      <Trophy size={14} className="drop-shadow-md" /> +{challenge.reward_wp}
                    </div>
                  </div>
                )}
              </div>

              <div className="flex items-center justify-between mt-4 pt-4 border-t border-slate-700/50">
                <div className="flex items-center gap-2">
                  <div className="flex items-center gap-1 text-[11px] font-bold text-slate-300 bg-slate-800/80 px-2.5 py-1.5 rounded-lg border border-slate-700">
                    <Flame size={12} className="text-orange-400" />
                    {challenge.duration_days} ngày
                  </div>
                  {!isActive && (
                    <div className={`flex items-center gap-1 text-[11px] font-bold px-2.5 py-1.5 rounded-lg border ${canAfford ? 'text-slate-300 bg-slate-800/80 border-slate-700' : 'text-red-400 bg-red-500/10 border-red-500/20'}`}>
                      Cược: {challenge.stake_wp} WP
                    </div>
                  )}
                </div>

                {!isActive && (
                  <button
                    onClick={() => handleJoin(challenge)}
                    disabled={!canAfford || isJoining}
                    className={`px-5 py-2 text-xs font-bold rounded-xl transition-all flex items-center justify-center gap-2 min-w-[100px] ${
                      canAfford 
                        ? 'bg-cyan-500/20 text-cyan-400 border border-cyan-500/30 hover:bg-cyan-500/30 active:scale-95 shadow-[0_0_10px_rgba(6,182,212,0.15)]' 
                        : 'bg-slate-800 text-slate-500 border border-slate-700 cursor-not-allowed opacity-60'
                    }`}
                  >
                    {isJoining ? <Loader2 size={14} className="animate-spin" /> : canAfford ? 'Tham gia' : <><Lock size={12} /> Thiếu WP</>}
                  </button>
                )}
                
                {isActive && activeEntry && (
                  <div className="text-xs font-bold text-emerald-500 flex items-center gap-1 bg-emerald-500/10 px-3 py-1.5 rounded-xl border border-emerald-500/20">
                    Tiến độ thực hiện: {activeEntry.progress_days} / {challenge.duration_days} ngày
                  </div>
                )}
              </div>

              {/* Thanh tiến độ siêu mỏng ở đáy Card */}
              {isActive && activeEntry && (
                <div className="absolute bottom-0 left-0 w-full h-1 bg-emerald-500/20">
                  <div 
                    className="h-full bg-emerald-400 shadow-[0_0_10px_rgba(52,211,153,0.8)] transition-all duration-1000 ease-out" 
                    style={{ width: `${Math.min((activeEntry.progress_days / challenge.duration_days) * 100, 100)}%` }} 
                  />
                </div>
              )}
            </div>
          );
        })}
        
        {filteredChallenges.length === 0 && !loading && (
          <div className="text-center p-8 border border-dashed border-slate-700 rounded-[2rem] text-slate-500 text-sm">
            Đang cập nhật thêm thử thách mới. Bạn quay lại sau nhé!
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useEffect, useState } from "react";
import { supabase } from "../lib/supabase";
import {
  Users,
  Shield,
  X,
  Loader2,
  Search,
  Flame,
  ChevronRight,
  Crown,
  ShieldCheck,
  Lock as LockIcon
} from "lucide-react";
import { toast } from "sonner";
import { AnimatePresence, motion } from "framer-motion";
import ClubDashboard from "./clubs/ClubDashboard";

interface Club {
  id: string;
  name: string;
  description: string | null;
  owner_id: string;
  member_count: number;
  total_wp: number;
  created_at: string;
  min_level_required: number;
  club_level: number;
}

// --- BỘ LUẬT NGŨ ĐẠI THỬ THÁCH ---
const REQ_WATER_ML = 50000;   // 1. 50 Lít nước
const REQ_LEVEL = 30;         // 2. Level 30
const REQ_STREAK = 21;        // 3. 21 ngày streak
const REQ_FRIENDS = 10;       // 4. 10 người bạn
const CREATION_FEE_WP = 10000; // 5. Phí 10.000 WP

export default function ClubsView({ userId }: { userId: string }) {
  const [clubs, setClubs] = useState<Club[]>([]);
  const [myRoles, setMyRoles] = useState<Record<string, string>>({});
  
  // STATE LƯU TRỮ CHỈ SỐ CỦA SẾP
  const [userStats, setUserStats] = useState({
    totalWater: 0,
    level: 0,
    currentStreak: 0,
    friendCount: 0,
    currentWP: 0,
    ownedClubs: 0
  });

  const [loading, setLoading] = useState(true);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [selectedClub, setSelectedClub] = useState<Club | null>(null);
  const [searchTerm, setSearchTerm] = useState("");

  const [newClubName, setNewClubName] = useState("");
  const [newClubDesc, setNewClubDesc] = useState("");
  const [newClubMinLevel, setNewClubMinLevel] = useState(1);
  const [isCreating, setIsCreating] = useState(false);
  const [joiningId, setJoiningId] = useState<string | null>(null);

  const fetchData = async () => {
    if (!userId || userId === 'undefined') return;

    setLoading(true);
    try {
      const [clubsRes, membersRes, waterRes, profileRes, friendsRes, ownedRes] = await Promise.all([
        supabase.from("clubs").select("*").order("total_wp", { ascending: false }),
        supabase.from("club_members").select("club_id, role").eq("user_id", userId),
        supabase.from("water_logs").select("amount, created_at").eq("user_id", userId).order('created_at', { ascending: false }),
        supabase.from("profiles").select("level, total_wp").eq("id", userId).maybeSingle(),
        // Thêm head: true để chỉ lấy count (tiết kiệm băng thông)
        supabase.from("friends").select("*", { count: 'exact', head: true }).eq("user_id", userId),
        supabase.from("clubs").select("*", { count: 'exact', head: true }).eq("owner_id", userId)
      ]);

      if (clubsRes.error) throw clubsRes.error;
      if (membersRes.error) throw membersRes.error;

      // 1. Tính toán lượng nước và Streak
      const logs = waterRes.data || [];
      const totalWater = logs.reduce((sum: number, log: { amount: number | null }) => sum + (log.amount || 0), 0);
      
      const uniqueDays = Array.from(new Set(logs.map((l: { created_at: string }) => l.created_at.split('T')[0]))).sort().reverse();
      const streak = uniqueDays.length > 0 ? uniqueDays.length : 0; // Tạm dùng tổng số ngày log làm streak

      // Cập nhật chỉ số
      setUserStats({
        totalWater,
        level: profileRes.data?.level || 0,
        currentStreak: streak,
        friendCount: friendsRes.count || 0,
        currentWP: profileRes.data?.total_wp || 0,
        ownedClubs: ownedRes.count || 0
      });

      setClubs(clubsRes.data || []);
      
      const rolesMap: Record<string, string> = {};
      (membersRes.data || []).forEach((m: { club_id: string; role: string }) => {
        rolesMap[m.club_id] = m.role;
      });
      setMyRoles(rolesMap);
      
    } catch (err: unknown) {
      console.error(err);
      toast.error("Không thể kết nối với bộ não Bang hội");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (userId && userId !== 'undefined') fetchData();
  }, [userId]);

  const handleJoin = async (clubId: string) => {
    setJoiningId(clubId);
    try {
      const { error } = await supabase.from("club_members").insert({
        club_id: clubId,
        user_id: userId,
        role: "member",
      });

      if (error) throw error;

      toast.success("Chào mừng đồng chí gia nhập bang! 🤝");
      await fetchData(); 
    } catch (err: unknown) {
      toast.error("Không thể gia nhập: " + (err instanceof Error ? err.message : String(err)));
    } finally {
      setJoiningId(null);
    }
  };

  const handleCreateClub = async (e: React.FormEvent) => {
    e.preventDefault();
    const trimmedName = newClubName.trim();
    const trimmedDesc = newClubDesc.trim();

    if (!trimmedName) {
      toast.error("Tên bang hội không được để trống sếp ơi!");
      return;
    }
    if (trimmedName.length < 3) {
      toast.error("Tên bang phải có ít nhất 3 ký tự.");
      return;
    }
    if (trimmedName.length > 50) {
      toast.error("Tên bang không được dài quá 50 ký tự.");
      return;
    }
    if (trimmedDesc.length > 200) {
      toast.error("Mô tả không được dài quá 200 ký tự.");
      return;
    }

    setIsCreating(true);
    try {
      // BƯỚC 1: KIỂM TRA TÊN TRÙNG LẶP
      const { data: existingClub } = await supabase
        .from('clubs')
        .select('name')
        .ilike('name', trimmedName)
        .maybeSingle();

      if (existingClub) {
        throw new Error("Tên bang hội này đã tồn tại. Vui lòng chọn tên khác.");
      }

      // BƯỚC 2: TẠO BANG MỚI
      const { data: newClubData, error: insertError } = await supabase
        .from("clubs")
        .insert({
          name: trimmedName,
          description: trimmedDesc,
          owner_id: userId,
          min_level_required: newClubMinLevel,
        })
        .select()
        .maybeSingle();

      if (insertError) throw insertError; // Lỗi từ DB
      if (!newClubData) throw new Error("Không thể lấy thông tin bang vừa tạo. Có thể do chính sách RLS."); // Lỗi không đọc lại được

      // BƯỚC 2.5: TỰ ĐỘNG THÊM CHỦ BANG LÀM THÀNH VIÊN (FIX LỖI CHAT & QUẢN LÝ)
      const { error: memberError } = await supabase
        .from("club_members")
        .insert({
          club_id: newClubData.id,
          user_id: userId,
          role: 'owner'
        });

      if (memberError) throw new Error("Lỗi thiết lập vai trò chủ bang: " + memberError.message);

      // BƯỚC 3: TRỪ THUẾ LẬP BANG
      const { error: wpError } = await supabase
        .from("profiles")
        .update({ total_wp: userStats.currentWP - CREATION_FEE_WP })
        .eq("id", userId);

      if (wpError) console.error("Lỗi khấu trừ WP:", wpError);

      toast.success(`Bang hội "${trimmedName}" đã khai sinh! Sếp đã chi ${CREATION_FEE_WP} WP! 🚩`);
      setShowCreateModal(false);
      setNewClubName("");
      setNewClubDesc("");
      setNewClubMinLevel(1);
      await fetchData(); 
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : "Lỗi tạo bang hội.");
    } finally {
      setIsCreating(false);
    }
  };

  const handleOpenCreateModal = async () => {
    const { totalWater, level, currentStreak, friendCount, currentWP, ownedClubs } = userStats;

    if (ownedClubs >= 1) return toast.error("Sếp đã lãnh đạo một bang rồi, nhường sân chơi cho ae khác nhé! 👑");

    // KIỂM TRA NGŨ ĐẠI THỬ THÁCH
    if (totalWater < REQ_WATER_ML) 
      return toast.error(`Thử thách 1: Cần 50L nước (Sếp có ${(totalWater/1000).toFixed(1)}L) 💧`);
    
    if (level < REQ_LEVEL) 
      return toast.error(`Thử thách 2: Cần Level ${REQ_LEVEL} (Sếp đang Level ${level}) 🆙`);
    
    if (currentStreak < REQ_STREAK) 
      return toast.error(`Thử thách 3: Cần chuỗi ${REQ_STREAK} ngày (Sếp có ${currentStreak} ngày) 🔥`);
    
    if (friendCount < REQ_FRIENDS) 
      return toast.error(`Thử thách 4: Cần ${REQ_FRIENDS} chiến hữu (Sếp có ${friendCount}) 🤝`);
    
    if (currentWP < CREATION_FEE_WP) 
      return toast.error(`Thử thách 5: Thiếu ${CREATION_FEE_WP.toLocaleString()} WP (Sếp còn ${currentWP.toLocaleString()}) 💎`);

    // XÁC NHẬN CHI TRẢ WP
    const { confirmDialog } = await import('@/store/useConfirmDialog');
    const ok = await confirmDialog({ title: 'Khai sinh Bang hội', message: `Sếp chuẩn bị hiến tế ${CREATION_FEE_WP.toLocaleString()} WP để khai sinh bang hội. Sẵn sàng chứ?`, confirmLabel: 'Xác nhận' });
    if (ok) {
      setShowCreateModal(true);
    }
  };

  const filteredClubs = clubs.filter(c => 
    c.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) {
    return (
      <div className="py-20 flex flex-col items-center gap-3">
        <Loader2 className="animate-spin text-cyan-400" size={32} />
        <p className="text-slate-500 text-sm animate-pulse">Đang triệu tập các bang phái...</p>
      </div>
    );
  }

  return (
    <>
      {!selectedClub && (
        <motion.div 
          initial={{ opacity: 0, y: 10 }} 
          animate={{ opacity: 1, y: 0 }}
          className="space-y-5 mt-6 pb-20"
        >
          <div className="flex items-center justify-between px-1">
            <div>
              <h3 className="text-white font-black text-2xl flex items-center gap-2">
                <Shield className="text-cyan-400" fill="currentColor" fillOpacity={0.2} />
                Cộng đồng
              </h3>
              <p className="text-slate-500 text-xs mt-1">Gia nhập bang, cùng nhau nạp nước</p>
            </div>

            <button
              onClick={handleOpenCreateModal}
              className="bg-gradient-to-r from-cyan-400 to-blue-600 text-white px-4 py-2 rounded-xl text-xs font-bold shadow-lg shadow-cyan-500/20 active:scale-95 transition-transform"
            >
              + Tạo Bang
            </button>
          </div>

          <div className="relative group">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-cyan-400 transition-colors" size={18} />
            <input 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              placeholder="Tìm kiếm bang hội..."
              className="w-full bg-slate-900/50 border border-white/5 rounded-2xl py-3.5 pl-12 pr-4 text-white text-sm outline-none focus:border-cyan-500/50 transition-all"
            />
          </div>

          <div className="grid gap-4">
            {filteredClubs.length === 0 ? (
              <div className="rounded-3xl border border-white/[0.06] bg-gradient-to-br from-slate-900/80 to-slate-900/40 p-8 text-center backdrop-blur-xl">
                <p className="text-lg font-black text-white">Chưa có bang hội nào</p>
                <p className="mt-2 text-sm text-slate-400 max-w-xs mx-auto">Hiện tại chưa có bang hội. Hãy tạo bang hội mới để bắt đầu!</p>
              </div>
            ) : filteredClubs.map((club) => {
              const myRole = myRoles[club.id]; 
              const isMember = !!myRole; 
              const isOwner = myRole === 'owner' || club.owner_id === userId; 
              const canJoin = userStats.level >= (club.min_level_required || 1);
              const isJoining = joiningId === club.id;

              return (
                <motion.div
                  key={club.id}
                  whileTap={{ scale: 0.98 }}
                  onClick={() => (isMember || isOwner) && setSelectedClub(club)}
                  className={`relative overflow-hidden bg-slate-900/40 border rounded-3xl p-5 transition-all group ${
                    (isMember || isOwner) ? "cursor-pointer border-white/10 hover:border-cyan-500/30" : "border-white/5"
                  }`}
                >
                  {(isMember || isOwner) && (
                    <div className="absolute -right-4 -top-4 w-24 h-24 bg-cyan-500/5 blur-3xl rounded-full" />
                  )}

                  <div className="flex justify-between items-start relative z-10">
                    <div className="space-y-1">
                      <div className="flex items-center gap-2">
                        <h4 className="text-white font-bold text-lg">{club.name}</h4>
                        {club.total_wp > 50000 && <Flame size={14} className="text-orange-500" fill="currentColor" />}
                      </div>
                      <p className="text-slate-400 text-sm line-clamp-1 pr-10">
                        {club.description || "Thành viên tích cực, nạp nước mỗi ngày"}
                      </p>
                    </div>

                    <div className="flex flex-col items-end gap-1">
                      <div className="bg-purple-500/10 p-2 rounded-xl text-purple-400">
                        <Users size={18} />
                      </div>
                      <span className="text-[10px] text-slate-500 font-medium">{club.member_count} mems</span>
                    </div>
                  </div>

                  <div className="mt-5 pt-4 border-t border-white/5 flex justify-between items-center relative z-10">
                    <div className="flex items-center gap-2">
                      <div className="flex items-center gap-1.5 text-cyan-400 text-xs font-bold bg-cyan-400/10 px-3 py-1.5 rounded-lg border border-cyan-400/20">
                        <Shield size={14} /> Cấp {club.club_level || 1}
                      </div>
                      {(club.min_level_required || 1) > 1 && (
                        <div className="flex items-center gap-1.5 text-slate-400 text-xs font-bold">
                          <ShieldCheck size={14} /> Y/C: Lv.{club.min_level_required}+
                        </div>
                      )}
                    </div>

                    {isOwner ? (
                      <div className="flex items-center gap-1.5 text-yellow-400 text-xs font-bold bg-yellow-400/10 px-3 py-1.5 rounded-lg border border-yellow-400/20">
                        <Crown size={14} /> Bang của sếp
                      </div>
                    ) : isMember ? (
                      <div className="flex items-center gap-1 text-cyan-400 text-xs font-bold hover:text-cyan-300 transition-colors">
                        Vào bang <ChevronRight size={14} />
                      </div>
                    ) : (
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          if (canJoin) {
                            handleJoin(club.id);
                          } else {
                            toast.error(`Cảnh giới chưa đủ! Yêu cầu cấp ${club.min_level_required} để gia nhập.`);
                          }
                        }}
                        disabled={isJoining || !canJoin}
                        className={`px-5 py-2 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-2 min-w-[100px] ${
                          canJoin
                            ? 'bg-cyan-500 text-black hover:bg-cyan-400 active:scale-95'
                            : 'bg-slate-800 text-slate-500 cursor-not-allowed'
                        }`}
                      >
                        {isJoining ? <Loader2 size={14} className="animate-spin" /> : canJoin ? "Gia nhập" : <LockIcon size={12} />}
                      </button>
                    )}
                  </div>
                </motion.div>
              );
            })}
          </div>
        </motion.div>
      )}

      <AnimatePresence>
        {selectedClub && (
          <motion.div
            key="club-dashboard-wrapper"
            initial={{ x: "100%" }}
            animate={{ x: 0 }}
            exit={{ x: "100%" }}
            transition={{ type: "spring", damping: 25, stiffness: 200 }}
            className="fixed inset-0 z-[100] bg-slate-950"
          >
            <ClubDashboard 
              clubId={selectedClub.id} 
              userId={userId}
              onBack={() => setSelectedClub(null)} 
            />
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {showCreateModal && (
          <div key="create-club-modal-wrapper" className="fixed inset-0 z-[150] flex items-center justify-center p-6">
