  );
}

import React, { useEffect, useState } from 'react';

export default function CountUp({ value }: { value: number }) {
  const [displayValue, setDisplayValue] = useState(value);

  useEffect(() => {
    const start = displayValue;
    const end = value;
    if (start === end) return;

    const duration = 800; // 0.8 giây
    const frameRate = 1000 / 60; // 60 FPS
    const totalFrames = Math.round(duration / frameRate);
    let frame = 0;

    const counter = setInterval(() => {
      frame++;
      const progress = frame / totalFrames;
      // Easing function cho mượt (chạy nhanh lúc đầu, chậm lúc sau)
      const easeOut = 1 - (1 - progress) * (1 - progress);
      const current = Math.round(start + (end - start) * easeOut);
      setDisplayValue(current);

      if (frame >= totalFrames) {
        clearInterval(counter);
        setDisplayValue(end);
      }
    }, frameRate);

    return () => clearInterval(counter);
  }, [value]);

  return <span>{displayValue.toLocaleString('vi-VN')}</span>;
}

import React, { useMemo } from 'react';
import { Activity, CloudSun, Moon, Droplets } from 'lucide-react';
import { motion } from 'framer-motion';

interface HydrationContextCardProps {
  profile: Record<string, unknown> | null;
  waterIntake: number;
  waterGoal: number;
  isWatchConnected: boolean;
  isWeatherSynced: boolean;
  isCalendarSynced: boolean;
  weeklyChartData: Record<string, unknown>[];
}

export default function HydrationContextCard(props: HydrationContextCardProps) {
  const { profile, waterIntake, waterGoal, weeklyChartData } = props;

  const contextAnalysis = useMemo(() => {
    // Activity level impact
    const activityMultiplier = {
      'sedentary': 1.0,
      'lightly_active': 1.1,
      'moderately_active': 1.2,
      'very_active': 1.3,
      'extremely_active': 1.4
    };

    const baseGoal = waterGoal || 2000;
    const activityLevel = profile?.activity_level || 'moderately_active';
    const activityAdjusted = Math.round(baseGoal * (activityMultiplier[activityLevel as keyof typeof activityMultiplier] || 1.2));

    // Weather impact (simulated - in real app would come from WeatherKit)
    const weatherImpact = {
      'hot': 1.2, // +20% in hot weather
      'warm': 1.1,
      'moderate': 1.0,
      'cool': 0.95,
      'cold': 0.9
    };

    const climate = profile?.climate || 'moderate';
    const weatherAdjusted = Math.round(activityAdjusted * (weatherImpact[climate as keyof typeof weatherImpact] || 1.0));

    // Sleep quality impact (deterministic placeholder until HealthKit data is available)
    const sleepSignal = String(profile?.id || profile?.nickname || 'digiwell')
      .split('')
      .reduce((sum, char) => sum + char.charCodeAt(0), 0) % 10;
    const sleepQuality = sleepSignal > 7 ? 'poor' : sleepSignal > 4 ? 'fair' : 'good';
    const sleepMultiplier = {
      'poor': 0.9, // -10% if poor sleep
      'fair': 0.95,
      'good': 1.0
    };
    const sleepAdjusted = Math.round(weatherAdjusted * sleepMultiplier[sleepQuality as keyof typeof sleepMultiplier]);

    // Current hydration state
    const currentPercent = (waterIntake / waterGoal) * 100;
    const adjustedPercent = (waterIntake / sleepAdjusted) * 100;

    let hydrationState: 'optimal' | 'good' | 'moderate' | 'low' | 'critical';
    let stateMessage: string;
    let stateColor: string;

    if (adjustedPercent >= 100) {
      hydrationState = 'optimal';
      stateMessage = 'Trạng thái hydration tối ưu';
      stateColor = 'text-emerald-400';
    } else if (adjustedPercent >= 80) {
      hydrationState = 'good';
      stateMessage = 'Hydration tốt, tiếp tục duy trì';
      stateColor = 'text-cyan-400';
    } else if (adjustedPercent >= 60) {
      hydrationState = 'moderate';
      stateMessage = 'Cần bổ sung thêm nước';
      stateColor = 'text-amber-400';
    } else if (adjustedPercent >= 30) {
      hydrationState = 'low';
      stateMessage = 'Thiếu hụt nước đáng kể';
      stateColor = 'text-orange-400';
    } else {
      hydrationState = 'critical';
      stateMessage = 'Cảnh báo mất nước';
      stateColor = 'text-red-400';
    }

    // Context factors
    const factors = [
      {
        icon: Activity,
        label: 'Hoạt động',
        value: String(activityLevel).replace('_', ' '),
        impact: activityAdjusted > baseGoal ? '+' + (activityAdjusted - baseGoal) : '0',
        color: 'text-blue-400'
      },
      {
        icon: CloudSun,
        label: 'Thời tiết',
        value: climate,
        impact: weatherAdjusted > activityAdjusted ? '+' + (weatherAdjusted - activityAdjusted) : '0',
        color: 'text-yellow-400'
      },
      {
        icon: Moon,
        label: 'Giấc ngủ',
        value: sleepQuality,
        impact: sleepAdjusted < weatherAdjusted ? (sleepAdjusted - weatherAdjusted) + '' : '0',
        color: 'text-purple-400'
      }
    ];

    return {
      baseGoal,
      activityAdjusted,
      weatherAdjusted,
      sleepAdjusted,
      hydrationState,
      stateMessage,
      stateColor,
      factors,
      currentPercent,
      adjustedPercent
    };
  }, [profile, waterIntake, waterGoal, weeklyChartData]);

  const stateConfig = {
    optimal: {
      bgColor: 'bg-emerald-500/10',
      borderColor: 'border-emerald-500/20',
      glowColor: 'shadow-emerald-500/20'
    },
    good: {
      bgColor: 'bg-cyan-500/10',
      borderColor: 'border-cyan-500/20',
      glowColor: 'shadow-cyan-500/20'
    },
    moderate: {
      bgColor: 'bg-amber-500/10',
      borderColor: 'border-amber-500/20',
      glowColor: 'shadow-amber-500/20'
    },
    low: {
      bgColor: 'bg-orange-500/10',
      borderColor: 'border-orange-500/20',
      glowColor: 'shadow-orange-500/20'
    },
    critical: {
      bgColor: 'bg-red-500/10',
      borderColor: 'border-red-500/20',
      glowColor: 'shadow-red-500/20'
    }
  };

  const config = stateConfig[contextAnalysis.hydrationState];

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, delay: 0.1 }}
      className="bg-slate-900/60 backdrop-blur-xl border border-white/5 rounded-2xl p-5 shadow-xl"
    >
      <div className="flex items-start justify-between mb-4">
        <div>
          <div className="flex items-center gap-2 mb-2">
            <div className={`w-8 h-8 rounded-full ${config.bgColor} border ${config.borderColor} flex items-center justify-center`}>
              <Droplets size={16} className={contextAnalysis.stateColor} />
            </div>
            <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">
              Health Context
            </span>
          </div>
          <h3 className="text-lg font-black text-white tracking-tight">
            Trạng thái sức khỏe
          </h3>
        </div>

        <div className={`rounded-xl ${config.bgColor} border ${config.borderColor} px-3 py-2 text-right shadow-lg ${config.glowColor}`}>
          <p className="text-[9px] uppercase tracking-[0.2em] text-slate-300 font-black">
            Adjusted Goal
          </p>
          <p className={`text-lg font-black ${contextAnalysis.stateColor}`}>
            {contextAnalysis.sleepAdjusted}
          </p>
          <p className="text-[9px] text-slate-500">ml</p>
        </div>
      </div>

      <p className={`text-sm font-medium leading-relaxed mb-4 ${contextAnalysis.stateColor}`}>
        {contextAnalysis.stateMessage}
      </p>

      <div className="space-y-3 mb-4">
        {contextAnalysis.factors.map((factor, index) => {
          const Icon = factor.icon;
          return (
            <div key={index} className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className={`w-6 h-6 rounded-full bg-slate-800/50 flex items-center justify-center`}>
                  <Icon size={12} className={factor.color} />
                </div>
                <div>
                  <p className="text-xs font-bold text-white">{factor.label}</p>
                  <p className="text-[10px] text-slate-500 capitalize">{String(factor.value)}</p>
                </div>
              </div>
              <div className="text-right">
                <p className={`text-xs font-black ${factor.impact.startsWith('+') ? 'text-emerald-400' : factor.impact.startsWith('-') ? 'text-red-400' : 'text-slate-400'}`}>
                  {factor.impact} ml
                </p>
              </div>
            </div>
          );
        })}
      </div>

      <div className="pt-3 border-t border-white/5">
        <div className="flex items-center justify-between text-xs mb-2">
          <span className="text-slate-400">Tiến độ hiện tại</span>
          <span className="text-white font-bold">
            {Math.round(contextAnalysis.adjustedPercent)}%
          </span>
        </div>
        <div className="w-full bg-slate-800/50 rounded-full h-1.5 overflow-hidden">
          <motion.div
            initial={{ width: 0 }}
            animate={{ width: `${Math.min(100, contextAnalysis.adjustedPercent)}%` }}
            transition={{ duration: 1, delay: 0.7 }}
            className={`h-full rounded-full ${contextAnalysis.stateColor.replace('text-', 'bg-')}/60`}
          />
        </div>
      </div>
    </motion.div>
  );
}

import React, { useState, useEffect } from 'react';
import { supabase } from '../lib/supabase';
import { toast } from 'sonner';
import { Activity, ArrowRight, ArrowLeft, Droplets, Loader2, User } from 'lucide-react';
import { track } from '@/lib/analytics';

import type { Profile } from '../models';
interface OnboardingModalProps {
  profile: Profile;
  onComplete: (weight: number, waterGoal: number, name: string) => void;
}

export default function OnboardingModal({ profile, onComplete }: OnboardingModalProps) {
  // Initialize with existing weight if available, otherwise empty
  const [step, setStep] = useState(1);
  const [name, setName] = useState<string>(profile?.nickname || '');
  const [weight, setWeight] = useState<string>(profile.weight ? String(profile.weight) : '');
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    if (profile?.id && !profile.onboarding_completed) {
      track('onboarding_started', { profile_id: profile.id });
    }
  }, []);

  const waterGoal = weight ? Math.round(Number(weight) * 30) : 0; // 30ml/kg/day

  const handleNextStep = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) {
      toast.error('Vui lòng nhập tên của bạn!');
      return;
    }
    setStep(2);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const numWeight = Number(weight);
    if (!numWeight || numWeight <= 0 || numWeight > 300) {
      toast.error('Vui lòng nhập cân nặng hợp lệ!');
      return;
    }

    setIsSubmitting(true);
    try {
      const { error } = await supabase
        .from('profiles')
        .update({ nickname: name.trim(), weight: numWeight, water_goal: waterGoal, onboarding_completed: true })
        .eq('id', profile.id);

      if (error) throw error;

      toast.success('Đã cập nhật mục tiêu của bạn!');
      track('onboarding_completed', { weight: numWeight, water_goal: waterGoal });
      onComplete(numWeight, waterGoal, name.trim());
    } catch (error: unknown) {
      toast.error(error instanceof Error ? error.message : 'Lỗi cập nhật hồ sơ!');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-950/80 backdrop-blur-md" />
      <div className="relative w-full max-w-sm bg-slate-900 border border-cyan-500/30 rounded-[2rem] p-8 shadow-[0_0_40px_rgba(6,182,212,0.15)] animate-in zoom-in-95 overflow-hidden">
        <div className="absolute -top-20 -right-20 w-40 h-40 bg-cyan-500/20 blur-[50px] rounded-full pointer-events-none" />
        <div className="absolute -bottom-20 -left-20 w-40 h-40 bg-purple-500/20 blur-[50px] rounded-full pointer-events-none" />
        
        <div className="relative z-10">
          {step === 1 && (
            <div className="animate-in fade-in slide-in-from-right-4 duration-500">
              <div className="w-16 h-16 bg-cyan-500/10 border border-cyan-500/20 rounded-2xl flex items-center justify-center mb-6 mx-auto shadow-inner">
                <User size={32} className="text-cyan-400" />
              </div>
              
              <h2 className="text-2xl font-black text-white text-center mb-2 tracking-tight">Xin chào! Bạn tên là gì?</h2>
              <p className="text-sm text-slate-400 text-center mb-8 leading-relaxed">
                Hãy cho hệ thống biết cách xưng hô với bạn nhé.
              </p>

              <form onSubmit={handleNextStep} className="space-y-6">
                <div>
                  <div className="relative flex items-center justify-center">
                    <input 
                      type="text" 
                      value={name}
                      onChange={e => setName(e.target.value)}
                      placeholder="Tên của bạn..."
                      className="w-full bg-slate-800/50 border-2 border-slate-700 rounded-xl py-4 px-4 text-center text-lg font-bold text-white focus:border-cyan-500 focus:ring-0 outline-none transition-all"
                      autoFocus
                    />
                  </div>
                </div>

                <button 
                  type="submit" 
                  disabled={!name.trim()}
                  className="w-full py-4 rounded-xl bg-gradient-to-r from-cyan-500 to-blue-500 text-white font-bold text-lg flex items-center justify-center gap-2 active:scale-95 transition-all shadow-[0_0_20px_rgba(6,182,212,0.4)] disabled:opacity-50 disabled:shadow-none hover:shadow-[0_0_30px_rgba(6,182,212,0.6)]"
                >
                  Tiếp tục <ArrowRight size={20} />
                </button>
              </form>
            </div>
          )}

          {step === 2 && (
            <div className="animate-in fade-in slide-in-from-right-4 duration-500">
              <button onClick={() => setStep(1)} className="absolute -top-4 -left-4 flex items-center gap-1 text-slate-400 hover:text-white transition-colors text-sm font-medium p-2">
                <ArrowLeft size={16} /> Quay lại
              </button>

              <div className="w-16 h-16 bg-cyan-500/10 border border-cyan-500/20 rounded-2xl flex items-center justify-center mb-6 mx-auto shadow-inner mt-6">
                <Activity size={32} className="text-cyan-400" />
              </div>
              
              <h2 className="text-2xl font-black text-white text-center mb-2 tracking-tight">Chào {name}! Bạn nặng bao nhiêu kg?</h2>
              <p className="text-sm text-slate-400 text-center mb-8 leading-relaxed">
                Hãy cho hệ thống biết cân nặng của bạn để AI tính toán lượng nước lý tưởng mỗi ngày nhé.
              </p>

              <form onSubmit={handleSubmit} className="space-y-6">
                <div>
                  <div className="relative flex items-center justify-center">
                    <input 
                      type="number" 
                      value={weight}
                      onChange={e => setWeight(e.target.value)}
                      placeholder="60"
                      className="w-32 bg-slate-800/50 border-2 border-slate-700 rounded-2xl py-3 text-center text-3xl font-black text-white focus:border-cyan-500 focus:ring-0 outline-none transition-all"
                      disabled={isSubmitting}
                      autoFocus
                    />
                    <span className="absolute right-6 text-slate-500 font-bold">kg</span>
                  </div>
                </div>

                <div className="bg-cyan-500/10 border border-cyan-500/20 rounded-2xl p-4 flex items-center justify-center gap-3">
                  <Droplets className="text-cyan-400" size={24} />
                  <div>
                    <p className="text-[10px] uppercase tracking-widest font-bold text-slate-400">Mục tiêu của bạn</p>
                    <p className="text-xl font-black text-cyan-300">{waterGoal} <span className="text-sm text-cyan-500/70">ml/ngày</span></p>
                  </div>
                </div>

                <button 
                  type="submit" 
                  disabled={isSubmitting || !weight}
                  className="w-full py-4 rounded-xl bg-gradient-to-r from-cyan-500 to-blue-500 text-white font-bold text-lg flex items-center justify-center gap-2 active:scale-95 transition-all shadow-[0_0_20px_rgba(6,182,212,0.4)] disabled:opacity-50 disabled:shadow-none hover:shadow-[0_0_30px_rgba(6,182,212,0.6)]"
                >
                  {isSubmitting ? <Loader2 size={20} className="animate-spin" /> : <>Bắt đầu hành trình <ArrowRight size={20} /></>}
                </button>
              </form>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

