          </div>
        </div>
      </div>

      {insights.length > 0 && (
        <div className="space-y-3">
          <div className="flex items-center gap-2 px-1">
            <Lightbulb size={16} className="text-amber-400" />
            <h3 className="text-sm font-black text-white">Insights</h3>
