import { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { useInfiniteQuery } from '@tanstack/react-query';
import { supabase } from '../lib/supabase';
import type { RealtimePostgresChangesPayload } from '@supabase/supabase-js';
import { readFeedCache, writeFeedCache } from '@/lib/sessionSecurity';
import type { SocialFeedPost } from '@/models';
import { appQueryKeys } from '@/lib/queryKeys';

const PAGE_SIZE = 10;

async function ensurePublicProfile(userId: string) {
  const { data: existing, error: existingError } = await supabase
    .from('public_profiles')
    .select('id')
    .eq('id', userId)
    .maybeSingle();
  if (existingError) throw existingError;

  if (!existing) {
    const { data: profile, error: profileError } = await supabase
      .from('profiles')
      .select('id, nickname, avatar_url, level, water_today, water_goal')
      .eq('id', userId)
      .single();
    if (profileError) throw profileError;

    if (profile) {
      const { error: upsertError } = await supabase.from('public_profiles').upsert({
        id: profile.id,
        nickname: profile.nickname || 'Người dùng DigiWell',
        avatar_url: profile.avatar_url,
        level: profile.level || 1,
        water_today: profile.water_today || 0,
        water_goal: profile.water_goal || 2000,
      }, { ignoreDuplicates: true });
      if (upsertError) throw upsertError;
    }
  }
}

type SocialFeedPostRow = SocialFeedPost & {
  social_post_likes?: Array<{ user_id: string }>;
};

async function fetchFeedPage(
  currentUserId: string,
  friendIdSet: Set<string>,
  offset: number,
): Promise<SocialFeedPost[]> {
  const { data, error } = await supabase
    .from('social_posts')
    .select(`
      *,
      author:profiles!social_posts_author_id_fkey (id, nickname, avatar_url, level, water_today, water_goal),
      social_post_likes (user_id)
    `)
    .order('created_at', { ascending: false })
    .range(offset, offset + PAGE_SIZE - 1);

  if (error) throw error;

  const visibleRows = (data || []).filter((post: SocialFeedPostRow) => {
    if (post.author_id === currentUserId) return true;
    if (post.post_kind === 'challenge') return friendIdSet.has(post.author_id);
    return post.visibility === 'public' || friendIdSet.has(post.author_id);
  });

  return visibleRows.map((post) => ({
    ...post,
    cheeredByMe:
      post.social_post_likes?.some((l: { user_id: string }) => l.user_id === currentUserId) ?? false,
  }));
}

export function useFeed(currentUserId: string | undefined, friendIds: string[] = []) {
  const [mergedPending, setMergedPending] = useState<SocialFeedPost[]>([]);
  const [newPostsCount, setNewPostsCount] = useState(0);
  const [pendingPosts, setPendingPosts] = useState<SocialFeedPost[]>([]);
  const initialUserId = useRef(currentUserId);
  const [activeUserId, setActiveUserId] = useState(currentUserId);
  const channelRef = useRef<ReturnType<typeof supabase.channel> | null>(null);
  const friendIdSet = useMemo(() => new Set(friendIds), [friendIds]);

  useEffect(() => {
    if (currentUserId === initialUserId.current) return;
    initialUserId.current = currentUserId;
    setActiveUserId(currentUserId);
    setMergedPending([]);
    setPendingPosts([]);
    setNewPostsCount(0);
  }, [currentUserId]);

  useEffect(() => {
    if (currentUserId && currentUserId !== 'undefined') {
      void ensurePublicProfile(currentUserId).catch(error => {
        console.error('Lỗi đồng bộ public profile:', error);
      });
    }
  }, [currentUserId]);

  const feedQuery = useInfiniteQuery({
    queryKey: appQueryKeys.feed(currentUserId, friendIds),
    queryFn: async ({ pageParam = 0 }) => {
      if (!currentUserId || currentUserId === 'undefined') return [];
      return fetchFeedPage(currentUserId, friendIdSet, pageParam);
    },
    getNextPageParam: (lastPage, _allPages, lastPageParam) => {
      if (lastPage.length < PAGE_SIZE) return undefined;
      return (lastPageParam as number) + PAGE_SIZE;
    },
    initialPageParam: 0,
    enabled: !!currentUserId && currentUserId !== 'undefined',
    staleTime: 30_000,
    placeholderData: () => {
      if (!currentUserId) return undefined;
      const cached = readFeedCache<SocialFeedPost[]>(currentUserId);
      if (!cached?.length) return undefined;
      return { pages: [cached], pageParams: [0] };
    },
  });

  useEffect(() => {
    if (feedQuery.data && currentUserId) {
      writeFeedCache(currentUserId, feedQuery.data.pages.flat());
    }
  }, [feedQuery.data, currentUserId]);

  useEffect(() => {
    if (!currentUserId || currentUserId === 'undefined') return;

    if (channelRef.current) {
      supabase.removeChannel(channelRef.current);
    }

    const channelId = `feed-${currentUserId}-${Date.now()}`;
    const channel = supabase.channel(channelId);
    channelRef.current = channel;

    channel
      .on(
        'postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'social_posts' },
        async (payload: RealtimePostgresChangesPayload<Record<string, unknown>>) => {
          const newPost = payload.new as { id: string;[key: string]: unknown };
          const { data } = await supabase
            .from('social_posts')
            .select('*, author:profiles!social_posts_author_id_fkey (id, nickname, avatar_url, level, water_today, water_goal)')
            .eq('id', newPost.id)
            .single();

          if (data) {
            setPendingPosts(prev => [data, ...prev]);
            setNewPostsCount(prev => prev + 1);
          }
        }
      );

    const subTimeout = setTimeout(() => {
      if (channelRef.current === channel) {
        channel.subscribe();
      }
    }, 50);

    return () => {
      clearTimeout(subTimeout);
      if (channelRef.current) {
        supabase.removeChannel(channelRef.current);
        channelRef.current = null;
      }
    };
  }, [currentUserId]);

  const posts = useMemo(() => {
    const base = feedQuery.data?.pages.flat() ?? [];
    const baseIds = new Set(base.map(p => p.id));
    const extra = mergedPending.filter(p => !baseIds.has(p.id));
    return [...extra, ...base];
  }, [mergedPending, feedQuery.data]);

  const loadMore = useCallback(() => {
    if (feedQuery.hasNextPage && !feedQuery.isFetchingNextPage) {
      feedQuery.fetchNextPage();
    }
  }, [feedQuery]);

  const showNewPosts = useCallback(() => {
    const formattedPending = pendingPosts.filter(Boolean).map(p => ({ ...p, cheeredByMe: false }));
    const base = feedQuery.data?.pages.flat() ?? [];
    const baseIds = new Set(base.map(p => p.id));
    const uniquePending = formattedPending.filter(p => !baseIds.has(p.id));
    const nextMerged = [...uniquePending, ...mergedPending];
    writeFeedCache(currentUserId, [...nextMerged, ...base]);
    setMergedPending(nextMerged);
    setPendingPosts([]);
    setNewPostsCount(0);
  }, [pendingPosts, currentUserId, feedQuery.data, mergedPending]);

  return {
    posts,
    isLoading: feedQuery.isLoading && feedQuery.fetchStatus !== 'idle',
    isFetchingMore: feedQuery.isFetchingNextPage,
    hasMore: !!feedQuery.hasNextPage,
    loadMore,
    newPostsCount,
    showNewPosts,
    refetch: () => feedQuery.refetch().then(() => {}),
  };
}

import { useState, useCallback } from 'react';
import { toast } from 'sonner';
import { supabase } from '../lib/supabase';

interface UsePostActionsProps {
  currentUserId: string | undefined;
}

export function usePostActions({ currentUserId }: UsePostActionsProps) {
  const [savedPosts, setSavedPosts] = useState<Set<string>>(new Set());
  const [cheeredPosts, setCheeredPosts] = useState<Set<string>>(new Set());

  const toggleSavePost = useCallback(async (postId: string) => {
    if (!currentUserId) return false;

    const isSaved = savedPosts.has(postId);
    const newState = !isSaved;

    setSavedPosts(prev => {
      const next = new Set(prev);
      if (newState) next.add(postId);
      else next.delete(postId);
      return next;
    });

    try {
      if (newState) {
        const { error } = await supabase.from('saved_posts').insert({ user_id: currentUserId, post_id: postId });
        if (error) throw error;
        toast.success('Đã lưu bài viết vào mục Lưu trữ', { icon: '🔖' });
      } else {
        const { error } = await supabase.from('saved_posts').delete().eq('user_id', currentUserId).eq('post_id', postId);
        if (error) throw error;
        toast.info('Đã bỏ lưu bài viết');
      }
      return true;
    } catch {
      setSavedPosts(prev => {
        const next = new Set(prev);
        if (isSaved) next.add(postId);
        else next.delete(postId);
        return next;
      });
      toast.error('Có lỗi xảy ra, vui lòng thử lại sau.');
      return false;
    }
  }, [currentUserId, savedPosts]);

  const cheersPost = useCallback(async (post: { id: string; author_id: string }) => {
    if (!currentUserId || !post.id) {
      toast.error("Lỗi dữ liệu: Bài viết này không có ID!");
      return false;
    }

    if (cheeredPosts.has(post.id)) {
      toast.error('Bạn đã cụng ly bài này rồi!');
      return false;
    }

    setCheeredPosts(prev => new Set(prev).add(post.id));
    const now = new Date();
    const today = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
    const tid = toast.loading('Đang cụng ly... 🍻', { icon: '💦' });

    try {
      const { data, error } = await supabase.rpc('action_cheers_post', {
        p_post_id: String(post.id),
        p_author_id: post.author_id ? String(post.author_id) : '00000000-0000-0000-0000-000000000000',
        p_local_date: today,
      });

      if (error) throw error;

      if (data === true) {
        toast.success('+200ml vào mục tiêu hôm nay!', { id: tid, icon: '✨' });
        await supabase.rpc('pulse_post', { p_post_id: String(post.id) });
        return true;
      } else {
        toast.error('Bạn đã cụng ly bài này rồi!', { id: tid });
        setCheeredPosts(prev => {
          const next = new Set(prev);
          next.delete(post.id);
          return next;
        });
        return false;
      }
    } catch {
      setCheeredPosts(prev => {
        const next = new Set(prev);
        next.delete(post.id);
        return next;
      });
      toast.error('Lỗi máy chủ, chưa thể cộng nước!', { id: tid, icon: '💦' });
      return false;
    }
  }, [currentUserId, cheeredPosts]);

  const deletePost = useCallback(async (postId: string) => {
    const { confirmDialog } = await import('@/store/useConfirmDialog');
    const ok = await confirmDialog({ title: 'Xóa bài viết', message: 'Bạn có chắc chắn muốn xóa bài viết này?', confirmLabel: 'Xóa', variant: 'danger' });
    if (!ok) return false;

    const tid = toast.loading('Đang xóa bài viết...');
    try {
      const { error } = await supabase
        .from('social_posts')
        .delete()
        .eq('id', postId)
        .eq('author_id', currentUserId);
      if (error) throw error;
      toast.success('Đã xóa bài viết thành công', { id: tid });
      return true;
    } catch (err: unknown) {
      console.error("Lỗi xóa bài viết:", err);
      toast.error('Không thể xóa bài viết lúc này!', { id: tid });
      return false;
    }
  }, []);

  const reportPost = useCallback(async (postId: string) => {
    const reasons = [
      '1. Spam / Quảng cáo',
      '2. Nội dung không phù hợp',
      '3. Quấy rối / Bắt nạt',
      '4. Thông tin sai lệch',
      '5. Bạo lực / Nội dung nhạy cảm',
      '6. Lý do khác',
    ];
    const choice = window.prompt(`Báo cáo bài viết - Chọn lý do (1-6):\n\n${reasons.join('\n')}`, '1');
    if (!choice) return false;
    const idx = parseInt(choice, 10);
    if (idx < 1 || idx > 6) return false;
    const reasonMap = ['spam', 'inappropriate', 'harassment', 'misinformation', 'violence', 'other'];
    const selectedReason = reasonMap[idx - 1];

    const tid = toast.loading('Đang gửi báo cáo đến hệ thống...');
    try {
      const { error } = await supabase.from('reports').insert({ target_id: postId, target_type: 'post', reporter_id: currentUserId, reason: selectedReason });
      if (error) throw error;
      toast.success('Đã ghi nhận báo cáo. Bài viết đã được ẩn khỏi Feed của bạn.', { id: tid });
      return true;
    } catch (err) {
      console.warn('Report error:', err);
      toast.error('Gửi báo cáo thất bại, vui lòng thử lại sau.', { id: tid });
      return false;
    }
  }, [currentUserId]);

  const editPost = useCallback(async (postId: string, currentContent: string) => {
    const newContent = window.prompt('Chỉnh sửa bài viết:', currentContent);
    if (newContent !== null && newContent.trim() !== currentContent) {
      const tid = toast.loading('Đang cập nhật...');
      try {
        const { error } = await supabase
          .from('social_posts')
          .update({ content: newContent.trim() })
          .eq('id', postId)
          .eq('author_id', currentUserId);
        if (error) throw error;
        toast.success('Đã cập nhật bài viết', { id: tid });
        return newContent.trim();
      } catch {
        toast.error('Lỗi khi cập nhật!', { id: tid });
        return null;
      }
    }
    return null;
  }, []);

  const joinChallenge = useCallback(async (opponentId: string) => {
    if (!currentUserId || !opponentId) {
      toast.error("Vui lòng đăng nhập để thách đấu!");
      return false;
    }

    if (currentUserId === opponentId) {
      toast.error("Sếp không thể tự thách đấu chính mình!");
      return false;
    }

    const tid = toast.loading('Đang gửi chiến thư...');
    try {
      const { error } = await supabase.from('hydration_battles').insert({ challenger_id: currentUserId, opponent_id: opponentId, stake_coins: 0, status: 'pending' });
      if (error) throw error;
      toast.success('Đã gửi chiến thư! Đối thủ sẽ nhận được thông báo trong Đấu trường. ⚔️', { id: tid });
      return true;
    } catch (err: unknown) {
      console.error("Lỗi gửi chiến thư:", err);
      toast.error('Không thể gửi chiến thư lúc này!', { id: tid });
      return false;
    }
  }, [currentUserId]);

  return {
    savedPosts,
    cheeredPosts,
    toggleSavePost,
    cheersPost,
    deletePost,
    reportPost,
    editPost,
    joinChallenge,
  };
}

import { useState, useEffect, useCallback } from 'react';
import { toast } from 'sonner';
import { normalizeActivity, normalizeClimate } from '../lib/profileNormalization';
import { updateProfileFields, type AppProfile } from '@/services/profile.service';
import { getBiometricEnabled } from '@/lib/sessionSecurity';

export interface AppSettings {
  displayName: string;
  avatarUrl: string;
  weight: number;
  height: number;
  age: number;
  gender: string;
  activity: string;
  climate: string;
  waterGoal: number;
  autoWaterGoal: boolean;
  syncHealth: boolean;
  smartReminders: boolean;
  reminderFrequency: '30 phút' | '1 giờ' | '2 giờ';
  quietHoursStart: string;
  quietHoursEnd: string;
  hapticsEnabled: boolean;
  unit: 'ml' | 'oz';
  themeColor: string;
  biometricEnabled: boolean;
  // Wellness fields
  sleepHours: number;           // Target sleep hours
  sleepQuality: number;         // Average quality (1-10)
  moodTracking: boolean;        // Enable mood check-ins
  syncWellnessData: boolean;    // Sync with Apple Health/Google Fit
  energyTracking: boolean;      // Track daily energy levels
}

const DEFAULT_SETTINGS: AppSettings = {
  displayName: '',
  avatarUrl: '',
  weight: 60,
  height: 170,
  age: 20,
  gender: 'Nam',
  activity: 'moderate',
  climate: 'temperate',
  waterGoal: 2000,
  autoWaterGoal: true,
  syncHealth: false,
  smartReminders: true,
  reminderFrequency: '1 giờ',
  quietHoursStart: '22:00',
  quietHoursEnd: '07:00',
  hapticsEnabled: true,
  unit: 'ml',
  themeColor: '#06b6d4', // Cyan
  biometricEnabled: false,
  // Wellness defaults
  sleepHours: 8,
  sleepQuality: 7,
  moodTracking: true,
  syncWellnessData: false,
  energyTracking: true,
};

export function useSettings(profile: AppProfile | null) {
  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);
  const [isSaving, setIsSaving] = useState(false);
  const [lastSync, setLastSync] = useState<Date | null>(null);

  // Load initial data
  useEffect(() => {
    if (!profile?.id) return;

    let isCancelled = false;

    const loadSettings = async () => {
      const profileId = profile!.id;
      const localKey = `digiwell_settings_${profileId}`;
      const cached = localStorage.getItem(localKey);
      const biometricEnabled = await getBiometricEnabled(profileId);

      if (isCancelled) return;

      if (cached) {
        const parsedCache = JSON.parse(cached);
        const normalizedActivity = normalizeActivity(String(profile!.activity) || parsedCache.activity || DEFAULT_SETTINGS.activity);
        const normalizedClimate = normalizeClimate(String(profile!.climate) || parsedCache.climate || DEFAULT_SETTINGS.climate);
        const normalizedSettings = {
          ...DEFAULT_SETTINGS,
          ...parsedCache,
          displayName: String(profile!.nickname) || '',
          avatarUrl: String(profile!.avatar_url) || parsedCache.avatarUrl || '',
          weight: Number(profile!.weight) || 60,
          height: Number(profile!.height) || 170,
          age: Number(profile!.age) || 20,
          gender: String(profile!.gender) || 'Nam',
          activity: normalizedActivity,
          climate: normalizedClimate,
          waterGoal: Number(profile!.water_goal) || parsedCache.waterGoal || 2000,
          biometricEnabled,
        };

        if (parsedCache.activity !== normalizedActivity || parsedCache.climate !== normalizedClimate) {
          localStorage.setItem(localKey, JSON.stringify(normalizedSettings));
        }

        setSettings({ ...normalizedSettings });
        return;
      }

       setSettings(prev => ({
         ...prev,
         displayName: String(profile!.nickname) || '',
         avatarUrl: String(profile!.avatar_url) || '',
         weight: Number(profile!.weight) || 60,
         height: Number(profile!.height) || 170,
         age: Number(profile!.age) || 20,
         gender: String(profile!.gender) || 'Nam',
         activity: String(normalizeActivity(String(profile!.activity) || DEFAULT_SETTINGS.activity)),
         climate: String(normalizeClimate(String(profile!.climate) || DEFAULT_SETTINGS.climate)),
         biometricEnabled,
          waterGoal: Number(profile!.water_goal) || 2000,
          // Wellness fields (with defaults if absent)
           sleepHours: Number(profile!.sleep_hours) || DEFAULT_SETTINGS.sleepHours,
           sleepQuality: Number(profile!.sleep_quality) || DEFAULT_SETTINGS.sleepQuality,
           moodTracking: Boolean(profile!.mood_tracking) || DEFAULT_SETTINGS.moodTracking,
           syncWellnessData: Boolean(profile!.sync_wellness_data) || DEFAULT_SETTINGS.syncWellnessData,
           energyTracking: Boolean(profile!.energy_tracking) || DEFAULT_SETTINGS.energyTracking,
       }));
    };

    void loadSettings();

    return () => {
      isCancelled = true;
    };
  }, [profile]);

  // Provide haptic feedback utility (Chỉ dùng cho UI gọi)
  const triggerHaptic = useCallback(() => {
    if (settings.hapticsEnabled && navigator.vibrate) {
      navigator.vibrate(50);
    }
  }, [settings.hapticsEnabled]);

  // Save to LocalStorage & Supabase
  const updateSettings = useCallback(async (
    newValues: Partial<AppSettings>,
    options?: { syncProfile?: boolean },
  ) => {
    if (!profile?.id || profile.id === 'undefined') return;
    
    setIsSaving(true);
    
    const updatedSettings = {
      ...settings,
      ...newValues,
      activity: normalizeActivity(newValues.activity ?? settings.activity),
      climate: normalizeClimate(newValues.climate ?? settings.climate),
    };
    setSettings(updatedSettings);
    
    // 1. Save to LocalStorage (Instant UI feedback)
    localStorage.setItem(`digiwell_settings_${profile.id}`, JSON.stringify(updatedSettings));

    // Apply Theme Color instantly
    if (newValues.themeColor) {
      document.documentElement.style.setProperty('--color-primary', newValues.themeColor);
    }

       // 2. Sync to Supabase in background
       try {
           // Đẩy đầy đủ các field quan trọng lên database
           if (options?.syncProfile !== false) {
              await updateProfileFields(profile!.id, {
             avatar_url: updatedSettings.avatarUrl,
             nickname: updatedSettings.displayName,
             weight: updatedSettings.weight,
             height: updatedSettings.height,
             age: updatedSettings.age,
             gender: updatedSettings.gender,
             activity: updatedSettings.activity,
             climate: updatedSettings.climate,
             water_goal: updatedSettings.waterGoal,
             // Wellness fields
             sleep_hours: updatedSettings.sleepHours,
             sleep_quality: updatedSettings.sleepQuality,
             mood_tracking: updatedSettings.moodTracking,
             sync_wellness_data: updatedSettings.syncWellnessData,
             energy_tracking: updatedSettings.energyTracking,
             updated_at: new Date().toISOString()
           });
         }
      setLastSync(new Date());
    } catch (error: unknown) {
      console.error('Lỗi đồng bộ Settings:', error);
      toast.message('Đã lưu cục bộ — sẽ đồng bộ khi có mạng', {
        description: 'Dữ liệu của bạn được an toàn.',
      });
    } finally {
      setIsSaving(false);
    }
  }, [settings, profile?.id]);

  return { settings, updateSettings, isSaving, lastSync, triggerHaptic };
}

import { useState, useCallback, useEffect, useRef } from 'react';
import { supabase } from '../lib/supabase';
import { toast } from 'sonner';

// ── State machine ──────────────────────────────────────────

export type BottleConnectionState =
  | 'idle'          // Not connected, not trying
  | 'connecting'    // Actively establishing connection
  | 'connected'     // Connected and ready
  | 'reconnecting'  // Connection lost, auto-retrying
  | 'error';        // Failed after retries

interface BottleMetrics {
  currentVolume: number;
  batteryLevel: number;
  signalStrength: number;
  temperature: number;
}

interface SyncLog {
  id: string;
  timestamp: Date;
  action: 'drink' | 'refill' | 'sync';
  amountChange?: number;
}

export interface EquippedBottleSkin {
  id: string;
  name?: string;
  description?: string;
  rarity?: string;
  meta_value?: string | null;
  image_url?: string | null;
}

interface ProfileBottleState {
  equipped_bottle_id: string | null;
  last_bottle_volume: number | null;
}

interface HydrationRpcResponse {
  exp_gained?: number;
  total_exp?: number;
  coins_gained?: number;
}

const HYDRATION_EVENT_NAME = 'hydrationEvent';
const BOTTLE_EQUIPPED_EVENT_NAME = 'bottleEquipped';

const clampVolume = (volume: number, capacity: number) =>
  Math.min(capacity, Math.max(0, volume));

const RECONNECT_BASE_MS = 1000;
const RECONNECT_MAX_MS = 16000;
const RECONNECT_MAX_ATTEMPTS = 5;

export const useSmartBottle = (userId: string | undefined, deviceId: string, capacity: number = 750) => {
  // State machine
  const [connectionState, setConnectionState] = useState<BottleConnectionState>('idle');
  const [isSyncing, setIsSyncing] = useState(false);
  const [lastError, setLastError] = useState<string | null>(null);

  const [equippedBottle, setEquippedBottle] = useState<EquippedBottleSkin | null>(null);
  const [metrics, setMetrics] = useState<BottleMetrics>({
    currentVolume: capacity,
    batteryLevel: 100,
    signalStrength: 100,
    temperature: 24,
  });
  const [syncLogs, setSyncLogs] = useState<SyncLog[]>([]);
  const metricsRef = useRef(metrics);
  const mountedRef = useRef(true);

  // Reconnection state
  const reconnectAttemptRef = useRef(0);
  const reconnectTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Derived values for backward compatibility
  const isConnected = connectionState === 'connected';

  useEffect(() => {
    metricsRef.current = metrics;
  }, [metrics]);

  useEffect(() => () => {
    mountedRef.current = false;
    cancelReconnect();
  }, []);

  // ── Reconnection engine ────────────────────────────────

  const cancelReconnect = useCallback(() => {
    if (reconnectTimerRef.current !== null) {
      clearTimeout(reconnectTimerRef.current);
      reconnectTimerRef.current = null;
    }
    reconnectAttemptRef.current = 0;
  }, []);

  const scheduleReconnect = useCallback(() => {
    if (!mountedRef.current) return;

    const attempt = reconnectAttemptRef.current + 1;

    if (attempt > RECONNECT_MAX_ATTEMPTS) {
      setConnectionState('error');
      setLastError(`Không thể kết nối lại sau ${RECONNECT_MAX_ATTEMPTS} lần thử.`);
      setIsSyncing(false);
      return;
    }

    setConnectionState('reconnecting');
    reconnectAttemptRef.current = attempt;

    const delay = Math.min(
      RECONNECT_BASE_MS * Math.pow(2, attempt - 1),
      RECONNECT_MAX_MS,
    );

    reconnectTimerRef.current = setTimeout(async () => {
      if (!mountedRef.current) return;

      setConnectionState('connecting');
      setIsSyncing(true);

      try {
        await new Promise(resolve => setTimeout(resolve, 800));
        if (!mountedRef.current) return;

        setConnectionState('connected');
        setMetrics(prev => ({
          ...prev,
          batteryLevel: Math.max(20, prev.batteryLevel - 5),
          signalStrength: 90,
        }));
        setLastError(null);
        cancelReconnect();
        setIsSyncing(false);
      } catch {
        if (!mountedRef.current) return;
        scheduleReconnect();
      }
    }, delay);
  }, []);

  // ── Simulate periodic signal check (demo mode) ─────────

  useEffect(() => {
    if (connectionState !== 'connected') return;

    const interval = setInterval(() => {
      if (connectionState !== 'connected') return;
      setMetrics(prev => ({
        ...prev,
        signalStrength: Math.max(40, prev.signalStrength - Math.floor(Math.random() * 5)),
        batteryLevel: Math.max(15, prev.batteryLevel - Math.floor(Math.random() * 2)),
      }));
    }, 30000);

    return () => clearInterval(interval);
  }, [connectionState]);

  const fetchEquippedBottle = useCallback(async (equippedBottleId?: string | null) => {
    if (!equippedBottleId) {
      setEquippedBottle(null);
      return;
    }

    const { data, error } = await supabase
      .from('shop_items')
      .select('id, name, description, rarity, meta_value, image_url')
      .eq('id', equippedBottleId)
      .maybeSingle();

    if (error) throw error;

    setEquippedBottle(data);
  }, []);

  useEffect(() => {
    if (!userId) {
      setEquippedBottle(null);
      setMetrics(prev => ({ ...prev, currentVolume: capacity }));
      return;
    }

    const fetchInitialState = async () => {
      try {
        const { data, error: profileError } = await supabase
          .from('profiles')
          .select('equipped_bottle_id, last_bottle_volume')
          .eq('id', userId)
          .single();

        if (profileError) throw profileError;

        const profileData = data as ProfileBottleState | null;

        const nextVolume =
          profileData?.last_bottle_volume === null || profileData?.last_bottle_volume === undefined
            ? capacity
            : clampVolume(profileData.last_bottle_volume, capacity);

        setMetrics(prev => ({ ...prev, currentVolume: nextVolume }));
        await fetchEquippedBottle(profileData?.equipped_bottle_id);
    } catch (err) {
        console.error('Lỗi lấy dữ liệu khởi tạo bình:', err);
      }
    };

    void fetchInitialState();
  }, [capacity, fetchEquippedBottle, userId]);

  useEffect(() => {
    const handleBottleEquipped = (event: Event) => {
      const customEvent = event as CustomEvent<{ equipped_bottle_id?: string | null }>;
      void fetchEquippedBottle(customEvent.detail?.equipped_bottle_id ?? null);
    };

    window.addEventListener(BOTTLE_EQUIPPED_EVENT_NAME, handleBottleEquipped);

    return () => {
      window.removeEventListener(BOTTLE_EQUIPPED_EVENT_NAME, handleBottleEquipped);
    };
  }, [fetchEquippedBottle]);

  const connectDevice = useCallback(async () => {
    if (connectionState === 'connected') return;

    cancelReconnect();
    setConnectionState('connecting');
    setIsSyncing(true);
    setLastError(null);

    try {
      await new Promise(resolve => setTimeout(resolve, 800));
      setConnectionState('connected');
      setMetrics(prev => ({ ...prev, batteryLevel: 85, signalStrength: 92, temperature: 20 }));
      toast.info('Đã kết nối DigiBottle (chế độ mô phỏng).');
    } catch {
      setConnectionState('error');
      setLastError('Kết nối thất bại. Vui lòng thử lại.');
    } finally {
      setIsSyncing(false);
    }
  }, [cancelReconnect, connectionState]);

  const disconnectDevice = useCallback(() => {
    cancelReconnect();
    setConnectionState('idle');
    setLastError(null);
    setIsSyncing(false);
    toast.info('Đã ngắt kết nối bình nước');
  }, [cancelReconnect]);

  const retryConnection = useCallback(() => {
    setConnectionState('idle');
    setLastError(null);
    reconnectAttemptRef.current = 0;
    void connectDevice();
  }, [connectDevice]);

  const handleDrinkEvent = useCallback(async (amount: number) => {
    if (connectionState !== 'connected' || !userId) {
      toast.error('Bình chưa được kết nối!');
      return;
    }

    setIsSyncing(true);

    try {
      const { data, error } = await supabase.rpc('process_hydration_event', {
        p_user_id: userId,
        p_amount_ml: amount,
      });

      if (error) throw error;

      const rpcData = (data ?? {}) as HydrationRpcResponse;
      const nextVolume = clampVolume(metricsRef.current.currentVolume - amount, capacity);

      setMetrics(prev => ({ ...prev, currentVolume: nextVolume }));

      const { error: profileUpdateError } = await supabase
        .from('profiles')
        .update({ last_bottle_volume: nextVolume })
        .eq('id', userId);

      if (profileUpdateError) {
        console.error('Lỗi lưu last_bottle_volume:', profileUpdateError);
      }

      const today = new Date();
      const todayStr = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}-${String(today.getDate()).padStart(2, '0')}`;

      const { data: insertedLog, error: logError } = await supabase.from('water_logs').insert({
        user_id: userId,
        amount: amount,
        name: 'DigiBottle',
        exp: rpcData.exp_gained ?? 0,
        day: todayStr,
      }).select('id, created_at').single();

      if (logError) console.error('Lỗi lưu water_logs:', logError);

      setSyncLogs(prev => [
        { id: Date.now().toString(), timestamp: new Date(), action: 'drink', amountChange: amount },
        ...prev,
      ]);

      window.dispatchEvent(new CustomEvent(HYDRATION_EVENT_NAME, {
        detail: {
          source: 'smart_bottle_demo',
          amount_ml: amount,
          current_volume: nextVolume,
          added_exp: rpcData.exp_gained ?? 0,
          new_total_exp: rpcData.total_exp ?? 0,
          new_coins: rpcData.coins_gained ?? 0,
          refresh_profile: true,
          refresh_water: true,
          occurred_at: insertedLog?.created_at || new Date().toISOString(),
          log_id: insertedLog?.id,
        },
      }));
    } catch (error) {
      console.error('Lỗi xử lý uống nước từ RPC:', error);
      toast.error('Không thể đồng bộ DigiBottle. Kiểm tra mạng rồi thử lại.');

      // Simulate connection drop on network failure
      if (connectionState === 'connected') {
        scheduleReconnect();
      }
    } finally {
      setIsSyncing(false);
    }
  }, [capacity, connectionState, userId, scheduleReconnect]);

  const refillBottle = useCallback(async () => {
    if (connectionState !== 'connected' || !userId) return;

    setIsSyncing(true);

    try {
      setMetrics(prev => ({ ...prev, currentVolume: capacity }));
      await supabase.from('profiles').update({ last_bottle_volume: capacity }).eq('id', userId);
      setSyncLogs(prev => [{ id: Date.now().toString(), timestamp: new Date(), action: 'refill' }, ...prev]);
      toast.success('Đã đổ đầy bình nước!');
    } catch (err) {
      console.error(err);
      toast.error('Không thể cập nhật trạng thái đổ đầy.');
    } finally {
      setIsSyncing(false);
    }
  }, [capacity, connectionState, userId]);

  const forceSync = useCallback(async () => {
    setIsSyncing(true);
    setSyncLogs(prev => [{ id: Date.now().toString(), timestamp: new Date(), action: 'sync' }, ...prev]);
    setTimeout(() => setIsSyncing(false), 1000);
  }, []);

  return {
    connectionState,
    isConnected,
    isSyncing,
    lastError,
    metrics,
    syncLogs,
    connectDevice,
    disconnectDevice,
    retryConnection,
    handleDrinkEvent,
    refillBottle,
    forceSync,
    equippedBottle,
    isDemoMode: true,
  };
};

import { useMemo } from 'react';
import type { HydrationSchedule } from '../lib/HydrationEngine';
import type { CalendarEventItem } from './useCalendarSync';

/**
 * Parse time string "HH:MM" to minutes since midnight
 */
function timeToMinutes(time: string): number | null {
  const [h, m] = time.split(':').map(Number);
  if (!Number.isFinite(h) || !Number.isFinite(m)) return null;
  return h * 60 + m;
}

/**
 * Format minutes since midnight back to "HH:MM"
 */
function minutesToTime(minutes: number): string {
  const normalized = Math.max(0, Math.min(23 * 60 + 59, minutes));
  const h = Math.floor(normalized / 60) % 24;
  const m = Math.round(normalized % 60);
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
}

type EventCategory = 'SPORT' | 'DEEP_WORK' | 'SOCIAL' | 'NORMAL';

type BusyWindow = {
  start: number;
  end: number;
  event: CalendarEventItem;
  category: EventCategory;
};

const PRE_EVENT_BUFFER_MINUTES = 10;
const POST_EVENT_BUFFER_MINUTES = 20;
const MIN_DRINK_SPACING_MINUTES = 25;
const EARLIEST_DRINK_MINUTES = 6 * 60;
const LATEST_DRINK_MINUTES = 23 * 60;
const SEARCH_WINDOW_MINUTES = 120;

function detectCategory(title: string): EventCategory {
  const t = title.toLowerCase();
  const sportKeywords = ['gym', 'tập', 'bóng đá', 'cầu lông', 'chạy', 'yoga', 'bơi', 'workout', 'sport', 'dance', 'tennis', 'đá banh'];
  const deepWorkKeywords = ['học', 'họp', 'thi', 'biên dịch', 'nghiên cứu', 'meeting', 'class', 'lecture', 'study', 'tiết'];
  const socialKeywords = ['cafe', 'tiệc', 'party', 'hẹn', 'đi chơi', 'shopping', 'date'];

  if (sportKeywords.some(kw => t.includes(kw))) return 'SPORT';
  if (deepWorkKeywords.some(kw => t.includes(kw))) return 'DEEP_WORK';
  if (socialKeywords.some(kw => t.includes(kw))) return 'SOCIAL';
  return 'NORMAL';
}

function buildBusyWindows(events: CalendarEventItem[]): BusyWindow[] {
  return events
    .filter(event => !event.isAllDay)
    .map((event) => {
      const startMinutes = timeToMinutes(event.start);
      const rawEndMinutes = timeToMinutes(event.end);

      if (startMinutes === null || rawEndMinutes === null) return null;

      const endMinutes = rawEndMinutes <= startMinutes ? 24 * 60 : rawEndMinutes;
      const category = detectCategory(event.title);

      return {
        start: Math.max(0, startMinutes - PRE_EVENT_BUFFER_MINUTES),
        end: Math.min(24 * 60, endMinutes + POST_EVENT_BUFFER_MINUTES),
        event,
        category,
      };
    })
    .filter((window): window is BusyWindow => !!window)
    .sort((a, b) => a.start - b.start);
}

function findOverlappingWindow(
  timeMinutes: number,
  busyWindows: BusyWindow[],
): BusyWindow | null {
  for (const window of busyWindows) {
    if (timeMinutes >= window.start && timeMinutes < window.end) {
      return window;
    }
  }
  return null;
}

function isTooCloseToUsedSlot(timeMinutes: number, usedSlots: number[]) {
  return usedSlots.some(slot => Math.abs(slot - timeMinutes) < MIN_DRINK_SPACING_MINUTES);
}

/**
 * Find the nearest available slot before an event,
 * or after an event if before doesn't work.
 */
function findAvailableSlot(
  desiredMinutes: number,
  busyWindows: BusyWindow[],
  usedSlots: number[],
): number {
  for (let offset = 0; offset <= SEARCH_WINDOW_MINUTES; offset += 15) {
    const candidates = offset === 0
      ? [desiredMinutes]
      : [desiredMinutes - offset, desiredMinutes + offset];

    for (const candidate of candidates) {
      if (candidate < EARLIEST_DRINK_MINUTES || candidate > LATEST_DRINK_MINUTES) continue;
      if (findOverlappingWindow(candidate, busyWindows)) continue;
      if (isTooCloseToUsedSlot(candidate, usedSlots)) continue;
      return candidate;
    }
  }

  // Keep original time but mark as busy
  return desiredMinutes;
}

export interface SmartScheduleItem {
  time: string;
  amount: number;
  note: string;
  isAdjusted: boolean;
  conflictingEvent?: string;
}

export function useSmartSchedule(
  baseSchedule: HydrationSchedule[] | null,
  calendarEvents: CalendarEventItem[],
  waterGoal: number,
): {
  schedule: SmartScheduleItem[];
  busyEventCount: number;
  totalAdjustedCount: number;
  hasEventsToday: boolean;
} {
  return useMemo(() => {
    if (!baseSchedule || baseSchedule.length === 0) {
      return {
        schedule: [],
        busyEventCount: 0,
        totalAdjustedCount: 0,
        hasEventsToday: calendarEvents.length > 0,
      };
    }

    let adjustedCount = 0;
    const busyWindows = buildBusyWindows(calendarEvents);
    const usedSlots: number[] = [];

    const smartSchedule: SmartScheduleItem[] = baseSchedule.map((item) => {
      const originalMinutes = timeToMinutes(item.time);
      if (originalMinutes === null) {
        return {
          time: item.time,
          amount: item.amount,
          note: item.note || 'Uống nước',
          isAdjusted: false,
        };
      }

      const overlapping = findOverlappingWindow(originalMinutes, busyWindows);

      if (!overlapping) {
        usedSlots.push(originalMinutes);
        return {
          time: item.time,
          amount: item.amount,
          note: item.note || 'Uống nước',
          isAdjusted: false,
        };
      }

      // Find best alternative slot
      const newMinutes = findAvailableSlot(originalMinutes, busyWindows, usedSlots);
      const isActuallyMoved = newMinutes !== originalMinutes;
      if (isActuallyMoved) adjustedCount++;
      usedSlots.push(newMinutes);

      // Adjust amount based on category
      let finalAmount = item.amount;
      let categoryNote = '';
      if (overlapping.category === 'SPORT') {
        finalAmount += 150;
        categoryNote = ' (+150ml bù thể thao)';
      } else if (overlapping.category === 'DEEP_WORK') {
        categoryNote = ' (ưu tiên tỉnh táo)';
      }

      return {
        time: minutesToTime(newMinutes),
        amount: finalAmount,
        note: isActuallyMoved
          ? `Né "${overlapping.event.title}"${categoryNote} - ${item.note || 'uống nước'}`
          : `Trùng "${overlapping.event.title}"${categoryNote} - uống nhanh ${finalAmount}ml`,
        isAdjusted: true,
        conflictingEvent: overlapping.event.title,
      };
    });

    return {
      schedule: smartSchedule.sort((a, b) => a.time.localeCompare(b.time)),
      busyEventCount: busyWindows.length,
      totalAdjustedCount: adjustedCount,
      hasEventsToday: calendarEvents.length > 0,
    };
  }, [baseSchedule, calendarEvents, waterGoal]);
}

import { useState, useRef, useCallback } from 'react';
import { toast } from 'sonner';
import { supabase } from '../lib/supabase';
import { useUIStore } from '../store/useUIStore';
import {
  buildProgressShareText,
  DEFAULT_SOCIAL_COMPOSER,
  type SocialComposerState,
} from '../lib/social';
import type { AppProfile } from '@/services/profile.service';

interface UseSocialComposerOptions {
  profile: AppProfile | null;
  setActiveTab?: (tab: string) => void;
  waterIntake?: number;
  waterGoal?: number;
  streak?: number;
  onPostPublished?: () => void;
}

interface UseSocialComposerReturn {
  socialComposer: SocialComposerState;
  setSocialComposer: React.Dispatch<React.SetStateAction<SocialComposerState>>;
  socialImageFile: File | null;
  setSocialImageFile: React.Dispatch<React.SetStateAction<File | null>>;
  socialImagePreview: string;
  setSocialImagePreview: React.Dispatch<React.SetStateAction<string>>;
  socialImageInputRef: React.RefObject<HTMLInputElement | null>;
  isPublishingSocialPost: boolean;
  showQuickDropCamera: boolean;
  setShowQuickDropCamera: React.Dispatch<React.SetStateAction<boolean>>;
  isPublishingQuickDrop: boolean;
  openSocialComposer: (kind?: SocialComposerState['postKind']) => void;
  closeSocialComposer: () => void;
  resetSocialComposer: () => void;
  openQuickDropCamera: () => void;
  closeQuickDropCamera: () => void;
  handleSocialImagePicked: (event: React.ChangeEvent<HTMLInputElement>) => void;
  handleQuickDropCapture: (blob: Blob) => Promise<void>;
  handlePublishSocialPost: (e: React.FormEvent) => Promise<void>;
}

export function useSocialComposer({
  profile,
  setActiveTab,
  waterIntake,
  waterGoal,
  streak,
  onPostPublished,
}: UseSocialComposerOptions): UseSocialComposerReturn {
  const [socialComposer, setSocialComposer] = useState<SocialComposerState>({ ...DEFAULT_SOCIAL_COMPOSER });
  const [socialImageFile, setSocialImageFile] = useState<File | null>(null);
  const [socialImagePreview, setSocialImagePreview] = useState('');
  const socialImageInputRef = useRef<HTMLInputElement>(null);
  const [isPublishingSocialPost, setIsPublishingSocialPost] = useState(false);
  const [showQuickDropCamera, setShowQuickDropCamera] = useState(false);
  const [isPublishingQuickDrop, setIsPublishingQuickDrop] = useState(false);

  const resetSocialComposer = useCallback(() => {
    if (socialImagePreview.startsWith('blob:')) {
      URL.revokeObjectURL(socialImagePreview);
    }
    setSocialComposer({ ...DEFAULT_SOCIAL_COMPOSER });
    setSocialImageFile(null);
    setSocialImagePreview('');
  }, [socialImagePreview]);

  const uploadSocialImage = async (file: File) => {
    if (!profile?.id) throw new Error('Vui lòng đăng nhập lại.');

    const extension = file.name.includes('.') ? file.name.split('.').pop()?.toLowerCase() : 'jpg';
    const safeExtension = extension || 'jpg';
    const filePath = `${profile.id}/${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${safeExtension}`;
    const { error } = await supabase!.storage.from('social-media').upload(filePath, file, {
      cacheControl: '3600',
      upsert: false,
      contentType: file.type || undefined,
    });
    if (error) throw error;
    return supabase!.storage.from('social-media').getPublicUrl(filePath).data.publicUrl;
  };

  const openSocialComposer = useCallback((kind: SocialComposerState['postKind'] = 'status') => {
    if (!profile?.id) {
      toast.error('Vui lòng đăng nhập lại để đăng bài.');
      return;
    }

    if (kind === 'story') {
      setActiveTab?.('feed');
      setShowQuickDropCamera(true);
      return;
    }

    const content = kind === 'progress'
      ? buildProgressShareText({
        nickname: profile?.nickname as string | undefined,
        waterIntake: waterIntake ?? 0,
        waterGoal: waterGoal ?? 2000,
        streak: streak ?? 0,
      })
      : '';

    resetSocialComposer();
    setSocialComposer({
      content,
      imageUrl: '',
      postKind: kind === 'progress' ? 'status' : kind,
      visibility: 'followers',
    });
    setActiveTab?.('feed');
    useUIStore.getState().setShowSocialComposer(true);
  }, [profile?.id, setActiveTab, waterIntake, waterGoal, streak, resetSocialComposer]);

  const closeSocialComposer = () => {
    resetSocialComposer();
    setShowQuickDropCamera(false);
    useUIStore.getState().setShowSocialComposer(false);
  };

  const openQuickDropCamera = () => {
    if (!profile?.id) {
      toast.error('Vui lòng đăng nhập lại để đăng Drop.');
      return;
    }
    setActiveTab?.('feed');
    setShowQuickDropCamera(true);
  };

  const closeQuickDropCamera = () => {
    setShowQuickDropCamera(false);
  };

  const handleSocialImagePicked = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith('image/')) {
      toast.error('Chỉ hỗ trợ ảnh JPG, PNG, WEBP hoặc HEIC.');
      event.target.value = '';
      return;
    }

    if (file.size > 5 * 1024 * 1024) {
      toast.error('Ảnh tối đa 5MB để upload nhanh hơn.');
      event.target.value = '';
      return;
    }

    if (socialImagePreview.startsWith('blob:')) {
      URL.revokeObjectURL(socialImagePreview);
    }

    const previewUrl = URL.createObjectURL(file);
    setSocialImageFile(file);
    setSocialImagePreview(previewUrl);
    setSocialComposer((prev: SocialComposerState) => ({ ...prev, imageUrl: '' }));
    event.target.value = '';
  };

  const handleQuickDropCapture = async (blob: Blob) => {
    if (!profile?.id) {
      toast.error('Vui lòng đăng nhập lại để đăng Drop.');
      return;
    }

    const file = new File([blob], `drop-${Date.now()}.jpg`, { type: blob.type || 'image/jpeg' });
    setIsPublishingQuickDrop(true);
    const toastId = toast.loading('Đang đăng Drop...');
    try {
      const imageUrl = await uploadSocialImage(file);
      const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();
      const { data, error } = await supabase!.from('social_posts').insert({
        author_id: profile.id,
        content: '',
        image_url: imageUrl,
        post_kind: 'story',
        visibility: 'followers',
        hydration_ml: waterIntake,
        streak_snapshot: streak,
        expires_at: expiresAt,
      }).select('id').single();
      if (error) throw error;
      if (!data?.id) throw new Error('Không nhận được Drop vừa tạo.');

      toast.success('Drop đã lên sóng.', { id: toastId });
      setShowQuickDropCamera(false);
      onPostPublished?.();
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      toast.error(message, { id: toastId });
    } finally {
      setIsPublishingQuickDrop(false);
    }
  };

  const handlePublishSocialPost = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!profile?.id) return;

    const trimmedContent = socialComposer.content.trim();
    const trimmedImageUrl = socialComposer.imageUrl.trim();

    if (socialComposer.postKind === 'story' && !trimmedImageUrl && !socialImageFile) {
      toast.error('Drop cần ảnh chụp nhanh trước khi đăng.');
      return;
    }

    if (socialComposer.postKind !== 'story' && !trimmedContent && !trimmedImageUrl && !socialImageFile) {
      toast.error('Viết gì đó hoặc thêm ảnh trước khi đăng.');
      return;
    }

    setIsPublishingSocialPost(true);
    const toastId = toast.loading(socialComposer.postKind === 'story' ? 'Đang đăng story...' : 'Đang đăng bài...');

    try {
      let imageUrl = trimmedImageUrl || null;
      if (socialImageFile) {
        imageUrl = await uploadSocialImage(socialImageFile);
      }

      const expiresAt = socialComposer.postKind === 'story'
        ? new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString()
        : null;

      const persistedPostKind = socialComposer.postKind === 'progress' ? 'status' : socialComposer.postKind;
      const { data, error } = await supabase!.from('social_posts').insert({
        author_id: profile.id,
        content: socialComposer.postKind === 'story' ? '' : trimmedContent,
        image_url: imageUrl,
        post_kind: persistedPostKind,
        visibility: socialComposer.visibility,
        hydration_ml: waterIntake,
        streak_snapshot: streak,
        expires_at: expiresAt,
      }).select('id').single();
      if (error) throw error;
      if (!data?.id) throw new Error('Không nhận được bài viết vừa tạo.');

      const successMessage = socialComposer.postKind === 'story'
        ? 'Drop đã lên sóng.'
        : socialComposer.postKind === 'challenge'
          ? 'Duel đã lên feed.'
          : 'Pulse đã xuất hiện trên feed.';
      toast.success(successMessage, { id: toastId });
      closeSocialComposer();
      onPostPublished?.();
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      toast.error(message, { id: toastId });
    } finally {
      setIsPublishingSocialPost(false);
    }
  };

  return {
    socialComposer,
    setSocialComposer,
    socialImageFile,
    setSocialImageFile,
    socialImagePreview,
    setSocialImagePreview,
    socialImageInputRef,
    isPublishingSocialPost,
    showQuickDropCamera,
    setShowQuickDropCamera,
    isPublishingQuickDrop,
    openSocialComposer,
    closeSocialComposer,
    resetSocialComposer,
    openQuickDropCamera,
    closeQuickDropCamera,
    handleSocialImagePicked,
    handleQuickDropCapture,
    handlePublishSocialPost,
  };
}

import { supabase } from './supabase';

interface AdminMetrics {
  dau: number;
  retentionD1: number;
  retentionD7: number;
  retentionD30: number;
  mrr: number;
  churnRate: number;
  totalUsers: number;
  totalPremium: number;
}

export async function fetchAdminMetrics(): Promise<AdminMetrics> {
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new Error('Not authenticated');

  const { data: profile } = await supabase
    .from('profiles')
    .select('role')
    .eq('id', user.id)
    .single();

  if (profile?.role !== 'admin') throw new Error('Access denied');

  const now = new Date();
  const today = now.toISOString().slice(0, 10);
  const daysAgo = (n: number) => new Date(now.getTime() - n * 86400000).toISOString();

  const [dauResult, totalUsers, totalPremium, checkoutStarted, checkoutSuccess, cohortD1, cohortD7, cohortD30] =
    await Promise.all([
      supabase.from('analytics_events').select('user_id', { count: 'exact', head: true })
        .gte('created_at', daysAgo(1)),
      supabase.from('profiles').select('id', { count: 'exact', head: true }),
      supabase.from('profiles').select('id', { count: 'exact', head: true })
        .not('stripe_subscription_id', 'is', null),
      supabase.from('analytics_events').select('id', { count: 'exact', head: true })
        .eq('event_name', 'checkout_started'),
      supabase.from('analytics_events').select('id', { count: 'exact', head: true })
        .eq('event_name', 'checkout_success'),
      supabase.from('analytics_events').select('user_id', { count: 'exact', head: true })
        .gte('created_at', daysAgo(2))
        .lt('created_at', daysAgo(1)),
      supabase.from('analytics_events').select('user_id', { count: 'exact', head: true })
        .gte('created_at', daysAgo(8))
        .lt('created_at', daysAgo(7)),
      supabase.from('analytics_events').select('user_id', { count: 'exact', head: true })
        .gte('created_at', daysAgo(31))
        .lt('created_at', daysAgo(30)),
    ]);

  const dau = dauResult.count ?? 0;
  const d1 = cohortD1.count ?? 1;
  const d7 = cohortD7.count ?? 1;
  const d30 = cohortD30.count ?? 1;

  const retentionD1 = d1 > 0 ? Math.round((dau / d1) * 100) : 0;
  const retentionD7 = d7 > 0 ? Math.round((dau / d7) * 100) : 0;
  const retentionD30 = d30 > 0 ? Math.round((dau / d30) * 100) : 0;

  const started = checkoutStarted.count ?? 0;
  const succeeded = checkoutSuccess.count ?? 0;
  const churnRate = started > 0
    ? Math.round(((started - succeeded) / started) * 100)
    : 0;

  const mrr = (totalPremium.count ?? 0) * 79900 / 100;

  return {
    dau,
    retentionD1,
    retentionD7,
    retentionD30,
    mrr,
    churnRate,
    totalUsers: totalUsers.count ?? 0,
    totalPremium: totalPremium.count ?? 0,
  };
}

import { describe, it, expect, vi, beforeEach } from 'vitest';

const mockInvoke = vi.fn();
let mockIsConfigured = true;

vi.mock('./supabase', () => ({
  supabase: { functions: { invoke: (...args: unknown[]) => mockInvoke(...args) } },
  get isSupabaseConfigured() { return mockIsConfigured; },
}));

describe('invokeAiGateway', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockIsConfigured = true;
  });

  it('returns data on success', async () => {
    mockInvoke.mockResolvedValue({ data: { result: 'ok' }, error: null });
    const { invokeAiGateway } = await import('./aiGateway');
    const result = await invokeAiGateway('advice', { msg: 'hello' });
    expect(result).toEqual({ result: 'ok' });
  });

  it('throws when not configured', async () => {
    mockIsConfigured = false;
    const { invokeAiGateway } = await import('./aiGateway');
    await expect(invokeAiGateway('advice', {})).rejects.toThrow('Cloud AI chưa được cấu hình.');
  });

  it('throws on generic invoke error', async () => {
    mockInvoke.mockResolvedValue({ data: null, error: new Error('Network fail') });
    const { invokeAiGateway } = await import('./aiGateway');
    await expect(invokeAiGateway('advice', {})).rejects.toThrow('Network fail');
  });

  it('extracts error from response context body', async () => {
    const context = { json: vi.fn().mockResolvedValue({ error: 'Server error!' }) };
    mockInvoke.mockResolvedValue({ data: null, error: Object.assign(new Error('bad request'), { context }) });
    const { invokeAiGateway } = await import('./aiGateway');
    await expect(invokeAiGateway('advice', {})).rejects.toThrow('Server error!');
  });

  it('throws parse error when context.json parse fails with different message', async () => {
    const context = { json: vi.fn().mockRejectedValue(new Error('parse fail')) };
    mockInvoke.mockResolvedValue({ data: null, error: Object.assign(new Error('bad request'), { context }) });
    const { invokeAiGateway } = await import('./aiGateway');
    await expect(invokeAiGateway('advice', {})).rejects.toThrow('parse fail');
  });

  it('throws when data contains error field', async () => {
    mockInvoke.mockResolvedValue({ data: { error: 'API error' }, error: null });
    const { invokeAiGateway } = await import('./aiGateway');
    await expect(invokeAiGateway('advice', {})).rejects.toThrow('API error');
  });

  it('throws when context.json body has no error field', async () => {
    const context = { json: vi.fn().mockResolvedValue({ ok: true }) };
    mockInvoke.mockResolvedValue({ data: null, error: Object.assign(new Error('bad request'), { context }) });
    const { invokeAiGateway } = await import('./aiGateway');
    await expect(invokeAiGateway('advice', {})).rejects.toThrow('bad request');
  });
});

describe('invokeAiGatewayStream', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockIsConfigured = true;
  });

  it('throws when not configured', async () => {
    mockIsConfigured = false;
    const { invokeAiGatewayStream } = await import('./aiGateway');
    const onEvent = vi.fn();
    await expect(invokeAiGatewayStream('advice', {}, onEvent)).rejects.toThrow('Cloud AI chưa được cấu hình.');
    expect(onEvent).not.toHaveBeenCalled();
  });

  it('throws on invoke error without context', async () => {
    mockInvoke.mockResolvedValue({ data: null, error: new Error('stream error') });
    const { invokeAiGatewayStream } = await import('./aiGateway');
    await expect(invokeAiGatewayStream('advice', {}, vi.fn())).rejects.toThrow('stream error');
  });

  it('throws message from context body on error', async () => {
    const context = { json: vi.fn().mockResolvedValue({ error: 'upstream fail' }) };
    mockInvoke.mockResolvedValue({ data: null, error: Object.assign(new Error('bad'), { context }) });
    const { invokeAiGatewayStream } = await import('./aiGateway');
    await expect(invokeAiGatewayStream('advice', {}, vi.fn())).rejects.toThrow('upstream fail');
  });

  it('throws when data is not a Response', async () => {
    mockInvoke.mockResolvedValue({ data: 'not-a-response', error: null });
    const { invokeAiGatewayStream } = await import('./aiGateway');
    await expect(invokeAiGatewayStream('advice', {}, vi.fn())).rejects.toThrow('AI gateway không trả về stream hợp lệ.');
  });

  it('throws when response has no body', async () => {
    mockInvoke.mockResolvedValue({ data: new Response(null, { status: 200 }), error: null });
    const { invokeAiGatewayStream } = await import('./aiGateway');
    await expect(invokeAiGatewayStream('advice', {}, vi.fn())).rejects.toThrow('AI gateway không trả về stream hợp lệ.');
  });

  it('parses SSE stream and calls onEvent for each block', async () => {
    const encoder = new TextEncoder();
    const stream = new ReadableStream({
      start(controller) {
        controller.enqueue(encoder.encode('event: delta\ndata: {"text":"hello"}\n\n'));
        controller.enqueue(encoder.encode('event: waterAction\ndata: {"waterAction":{"drink":250}}\n\n'));
        controller.enqueue(encoder.encode('event: done\ndata: {}\n\n'));
        controller.close();
      },
    });
    mockInvoke.mockResolvedValue({ data: new Response(stream), error: null });

    const { invokeAiGatewayStream } = await import('./aiGateway');
    const onEvent = vi.fn();
    await invokeAiGatewayStream('advice', {}, onEvent);

    expect(onEvent).toHaveBeenCalledTimes(3);
    expect(onEvent).toHaveBeenCalledWith({ type: 'delta', text: 'hello' });
    expect(onEvent).toHaveBeenCalledWith({ type: 'waterAction', waterAction: { drink: 250 } });
    expect(onEvent).toHaveBeenCalledWith({ type: 'done' });
  });

  it('handles error event type', async () => {
    const encoder = new TextEncoder();
    const stream = new ReadableStream({
      start(controller) {
        controller.enqueue(encoder.encode('event: error\ndata: {"error":"oops"}\n\n'));
        controller.close();
      },
    });
