export const QuickDropCameraUltimate = ({ 
  isOpen, 
  isPublishing, 
  onCapture, 
  onClose 
}: QuickDropCameraProps) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  const [cameraFacing, setCameraFacing] = useState<'environment' | 'user'>('environment');
  const [cameraError, setCameraError] = useState('');
  const [isCameraLoading, setIsCameraLoading] = useState(false);
  const [countdown, setCountdown] = useState<number | null>(null);
  const [showSettings, setShowSettings] = useState(false);
  const [gridEnabled, setGridEnabled] = useState(true);
  const [flashEnabled, setFlashEnabled] = useState(false);
  const [focusPoint, setFocusPoint] = useState<{ x: number; y: number } | null>(null);
  const [zoom, setZoom] = useState(1);

  const stopCamera = () => {
    streamRef.current?.getTracks().forEach(track => track.stop());
    streamRef.current = null;
  };

  useEffect(() => {
    if (!isOpen) {
      stopCamera();
      setShowSettings(false);
      setCountdown(null);
      return;
    }

    let isMounted = true;
    const startCamera = async () => {
      if (!navigator.mediaDevices?.getUserMedia) {
        setCameraError('Thiết bị này chưa hỗ trợ camera trực tiếp.');
        return;
      }

      setIsCameraLoading(true);
      setCameraError('');
      stopCamera();

      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          audio: false,
          video: {
            facingMode: cameraFacing,
            width: { ideal: 1080 },
            height: { ideal: 1440 },
          },
        });

        if (!isMounted) {
          stream.getTracks().forEach(track => track.stop());
          return;
        }

        streamRef.current = stream;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          await videoRef.current.play();
        }
      } catch (error) {
        console.error('[QuickDropCamera] Camera error:', error);
        if (isMounted) {
          setCameraError('Không mở được camera. Kiểm tra quyền camera rồi thử lại.');
        }
      } finally {
        if (isMounted) setIsCameraLoading(false);
      }
    };

    void startCamera();
    return () => {
      isMounted = false;
      stopCamera();
    };
  }, [cameraFacing, isOpen]);

  // Handle countdown completion
  useEffect(() => {
    if (countdown === null) return;

    if (countdown === 0) {
      handleCapture();
      setCountdown(null);
      return;
    }

    const timer = setTimeout(() => {
      setCountdown(countdown - 1);
    }, 1000);

    return () => clearTimeout(timer);
  }, [countdown]);

  // Handle focus tap
  const handleFocusTap = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!videoRef.current || showSettings) return;

    const rect = e.currentTarget.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    setFocusPoint({ x, y });
    setTimeout(() => setFocusPoint(null), 1000);
  };

  const handleCapture = () => {
    const video = videoRef.current;
    const canvas = canvasRef.current;
    if (!video || !canvas || isPublishing || isCameraLoading) return;

    const width = video.videoWidth;
    const height = video.videoHeight;
    if (!width || !height) {
      toast.error('Camera chưa sẵn sàng.');
      return;
    }

    canvas.width = width;
    canvas.height = height;
    const context = canvas.getContext('2d');
    if (!context) {
      toast.error('Không thể chụp Drop lúc này.');
      return;
    }

    // Apply zoom if needed
    if (zoom !== 1) {
      context.save();
      context.scale(zoom, zoom);
      context.translate(-((zoom - 1) * width) / 2, -((zoom - 1) * height) / 2);
      context.drawImage(video, 0, 0, width, height);
      context.restore();
    } else {
      context.drawImage(video, 0, 0, width, height);
    }

    canvas.toBlob((blob) => {
      if (!blob) {
        toast.error('Không thể tạo ảnh Drop.');
        return;
      }
      void onCapture(blob);
    }, 'image/jpeg', 0.95);
  };

  const startCountdown = () => {
    setCountdown(3);
  };

  const switchCamera = () => {
    setCameraFacing(prev => prev === 'environment' ? 'user' : 'environment');
    setZoom(1);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[120] flex justify-center bg-slate-950">
      <style>{`
        .number-glow {
          text-shadow: 0 0 30px rgba(34, 211, 238, 0.6);
        }
      `}</style>

      <motion.div
        ref={containerRef}
        initial={{ opacity: 0, scale: 0.98 }}
        animate={{ opacity: 1, scale: 1 }}
        exit={{ opacity: 0, scale: 0.98 }}
        transition={{ duration: 0.2 }}
